import { t } from '../i18n'
import { Game, GameEvent } from '../rules/game'

/** The combat log line(s) of an event, in the current language; `sides`: the name of each player's troop */
export function describeEvent(game: Game, event: GameEvent, sides: [string, string]): string[] {
  const text = t().onagro
  const name = (id: number) => game.unit(id).sheet.name
  const spellName = (id: string) => text.spells[id as keyof typeof text.spells].name
  const log = text.log
  switch (event.type) {
  case 'turn-start': return [log.turnStart(event.turn, sides[event.initiative])]
  case 'first-player': return [log.first(sides[event.player])]
  case 'recovery': return [log.recovery(name(event.unitId), event.roll, event.morale, event.recovered)]
  case 'move': return [log.move(name(event.unitId))]
  case 'disengage': return [log.disengage(name(event.unitId), name(event.by))]
  case 'hold': return [log.hold(name(event.unitId))]
  case 'shot': {
    if (event.outOfRange) return [log.shotLost(name(event.shooterId), name(event.targetId))]
    const lines = [log.shot(name(event.shooterId), name(event.targetId), event.roll, event.needed, event.hit)]
    if (event.hit && event.hitUnitId !== event.targetId && event.hitUnitId !== null) lines.push(log.friendly(name(event.hitUnitId)))
    return lines
  }
  case 'strike': {
    const attack = event.roll.attackFinal.join(' ')
    const defense = event.roll.defense.join(' ')
    if (event.kind === 'spell' || event.attackerId === null) return [log.strikeNoAttacker(name(event.defenderId), attack, defense, event.dealt)]
    return [log.strike(name(event.attackerId), name(event.defenderId), attack, defense, event.dealt, event.backlash)]
  }
  case 'damage': return [log.damage(name(event.unitId), event.amount, event.hp)]
  case 'last-breath': return [log.lastBreath(name(event.unitId), event.roll, event.saved)]
  case 'out': return [log.out(name(event.unitId), log.reasons[event.reason])]
  case 'cast': return [log.cast(name(event.casterId), spellName(event.spell))]
  case 'heal': return [log.heal(name(event.unitId), event.amount, event.hp)]
  case 'shield': return [log.shield(name(event.unitId), event.turns)]
  case 'shield-ended': return [log.shieldEnded(name(event.unitId))]
  case 'morale-test': return [(event.cause === 'fear' ? log.fear : log.morale)(name(event.unitId), event.roll, event.morale, event.passed)]
  case 'save': return [log.save(name(event.unitId), event.roll, event.needed, event.saved)]
  case 'raised': return [log.raised(name(event.unitId))]
  case 'retreat': return [log.retreat(name(event.unitId))]
  case 'turn-end': return [log.turnEnd(event.turn)]
  case 'game-over': {
    const win = event.winner === 'draw' ? text.over.draw : text.over.win(sides[event.winner])
    return [log.gameOver(`${win} ${text.over.score(event.scores[0], event.scores[1])}`)]
  }
  }
}
