/**
 * Movement of ONAGRO (guide, "Movimentação"): hexes counted one by one,
 * terrain by type, and the Zone of Control. Pure: it only needs the map and
 * a way to ask who stands on a hex.
 *
 * - easy terrain costs 1 per hex, hard terrain 2 (half the MO, rounded down)
 * - very hard terrain (river, lake): the unit moves only 1 hex, and it also
 *   moves only 1 hex when it starts the move inside one
 * - blocked terrain (wall, rock, mountain) cannot be entered
 * - allies can be crossed but not stopped on; enemies cannot be crossed
 * - entering a hex next to an enemy (its ZOC) ends the move
 */
import { Axial, hexKey, hexNeighbors } from '../hex'
import { MapData, Terrain, inMap, terrainAt } from './terrain'
import { Player, UnitState, inPlay } from './units'

export interface MoveContext {
  map: MapData
  /** The unit standing on the hex, if any */
  unitAt(hex: Axial): UnitState | null
}

/** Movement spent to enter a hex of this terrain; Infinity when it cannot be entered */
export function entryCost(terrain: Terrain, budget: number): number {
  switch (terrain.move) {
  case 'easy': return 1
  case 'hard': return 2
  case 'veryHard': return budget
  case 'blocked': return Infinity
  }
}

/** Movement points a unit starts a move with: its MO, or 1 inside very hard terrain */
export function startBudget(ctx: MoveContext, unit: UnitState): number {
  const here = unit.pos ? terrainAt(ctx.map, unit.pos) : null
  return here?.move === 'veryHard' ? Math.min(1, unit.sheet.stats.mo) : unit.sheet.stats.mo
}

/** Enemy units (in play) next to a hex */
export function enemiesAround(ctx: MoveContext, hex: Axial, owner: Player): UnitState[] {
  const result: UnitState[] = []
  for (const n of hexNeighbors(hex)) {
    const unit = ctx.unitAt(n)
    if (unit && inPlay(unit) && unit.owner !== owner) result.push(unit)
  }
  return result
}

/** Is the hex inside the Zone of Control of an enemy of `owner`? */
export const isInEnemyZoc = (ctx: MoveContext, hex: Axial, owner: Player): boolean => enemiesAround(ctx, hex, owner).length > 0

export interface MovementMap {
  start: Axial
  /** Hexes the unit can stop on (the start hex is not included) */
  range: Axial[]
  canStopAt(hex: Axial): boolean
  costTo(hex: Axial): number
  /** Hexes from the start to `hex`, both included; empty when it cannot be reached */
  pathTo(hex: Axial): Axial[]
}

/**
 * Everything `unit` can reach with one move. A unit that starts inside an
 * enemy ZOC can leave it here: what leaving costs (the free attack of
 * disengaging) is a rule of the turn, not of the map.
 */
export function movementMap(ctx: MoveContext, unit: UnitState, options: { ignoreZoc?: boolean } = {}): MovementMap {
  if (!unit.pos) throw new Error('The unit is not on the map')
  const start = unit.pos
  const budget = startBudget(ctx, unit)
  const cost = new Map<string, number>([[hexKey(start), 0]])
  const previous = new Map<string, Axial>()
  const settled = new Set<string>()
  const open: { hex: Axial, cost: number }[] = [{ hex: start, cost: 0 }]

  while (open.length > 0) {
    // small maps: picking the cheapest of a short list is fast enough
    let best = 0
    for (let i = 1; i < open.length; i++) if (open[i].cost < open[best].cost) best = i
    const { hex, cost: here } = open.splice(best, 1)[0]
    const key = hexKey(hex)
    if (settled.has(key)) continue
    settled.add(key)

    // entering an enemy ZOC ends the move (the start hex is where it begins)
    if (key !== hexKey(start) && !options.ignoreZoc && isInEnemyZoc(ctx, hex, unit.owner)) continue

    for (const next of hexNeighbors(hex)) {
      if (!inMap(ctx.map, next)) continue
      const terrain = terrainAt(ctx.map, next)
      if (!terrain) continue
      const occupant = ctx.unitAt(next)
      if (occupant && inPlay(occupant) && occupant.owner !== unit.owner) continue
      const total = here + entryCost(terrain, budget)
      if (total > budget) continue
      const nextKey = hexKey(next)
      if (total < (cost.get(nextKey) ?? Infinity)) {
        cost.set(nextKey, total)
        previous.set(nextKey, hex)
        open.push({ hex: next, cost: total })
      }
    }
  }

  const startKey = hexKey(start)
  const range: Axial[] = []
  const stoppable = new Set<string>()
  for (const key of cost.keys()) {
    if (key === startKey) continue
    const [q, r] = key.split(',').map(Number)
    const occupant = ctx.unitAt({ q, r })
    if (occupant && inPlay(occupant)) continue
    range.push({ q, r })
    stoppable.add(key)
  }

  return {
    start,
    range,
    canStopAt: hex => stoppable.has(hexKey(hex)),
    costTo: hex => cost.get(hexKey(hex)) ?? Infinity,
    pathTo(hex) {
      if (!stoppable.has(hexKey(hex))) return []
      const path: Axial[] = [hex]
      let key = hexKey(hex)
      while (key !== startKey) {
        const before = previous.get(key)
        if (!before) return []
        path.unshift(before)
        key = hexKey(before)
      }
      return path
    }
  }
}
