/**
 * The tutorial match, step by step. Pure data (no engine, no UI).
 *
 * Map 1, the player with the Humanos de Rubrágua (side 0, west) against the Mortos-Vivos (side 1,
 * east), played by the script, not by the AI. Every action of both sides and every die is fixed
 * here, so the match always plays out the same way and walks through every rule of the guide.
 * tests/tutorial.test.ts plays it on the real rules: each action must be legal, each step must use
 * exactly its dice, and the lessons it promises must happen. Changed a rule, a sheet or map 1?
 * That test says which step broke.
 *
 * Hexes are written as [column, row] (offset), as in map-terrain.ts.
 */

export type Hex = [number, number]

export const hexOf = ([col, row]: Hex): Axial => offsetToAxial(col, row, 'pointy')

/** Unit ids: the troop order of HUMAN_TROOP (0-5) and UNDEAD_TROOP (6-11) */
export const U = {
  carolina: 0, mage: 1, archer: 2, inf1: 3, inf2: 4, inf3: 5,
  sombra: 6, cultist: 7, flag1: 8, flag2: 9, skeleton: 10, skArcher: 11
} as const

/** The tutorial is a whole match: the 6 turns of the guide */
export const TUTORIAL_TURNS = DEFAULT_MAX_TURNS

/** Left against right, as a new player deploys and as the game deploys by default */
export const TUTORIAL_EDGES: [Edge, Edge] = ['west', 'east']

/** Both troops in the standard formation (defaultDeployment), in troop order */
export const TUTORIAL_PLACEMENTS: [Axial[], Axial[]] = [
  defaultDeployment(MAP1, HUMAN_TROOP, TUTORIAL_EDGES[0]).map(p => p.pos),
  defaultDeployment(MAP1, UNDEAD_TROOP, TUTORIAL_EDGES[1]).map(p => p.pos)
]

export function tutorialArmies(): [Placement[], Placement[]] {
  return [
    HUMAN_TROOP.units.map((sheet, i) => ({ sheet, pos: TUTORIAL_PLACEMENTS[0][i], commander: sheet === HUMAN_TROOP.commander })),
    UNDEAD_TROOP.units.map((sheet, i) => ({ sheet, pos: TUTORIAL_PLACEMENTS[1][i], commander: sheet === UNDEAD_TROOP.commander }))
  ]
}

/** The initiative roll of turn 1, rolled when the game is created */
export const SETUP_DICE = [5, 2]

export type TutorialAction =
  | { a: 'first', player: Player }
  | { a: 'move', unit: number, to: Hex }
  | { a: 'shoot', unit: number, target: number }
  | { a: 'cast', unit: number, spell: SpellId, hex?: Hex, target?: number }
  | { a: 'hold', unit: number }
  | { a: 'melee', unit: number, target: number }

/** Parts of the HUD a text step points at: both troop lists, the turn and phase, the dice of the last attack */
export type TutorialUi = 'rosters' | 'turn' | 'dice'

export const LESSONS = [
  'goal', 'sheet', 'turn-order', 'initiative', 'select', 'move', 'activated', 'hard-terrain', 'blocked-terrain', 'hold',
  'enemy-phase', 'enemy-shot', 'ranged', 'cover', 'dice', 'excess', 'area-spell', 'recharge', 'zoc', 'engaged',
  'fear-spell', 'shaken', 'save', 'melee', 'block', 'backlash', 'pd-bonus', 'causes-fear', 'inspiration', 'mindless',
  'recovery', 'disengage', 'friendly-fire', 'raise-dead', 'frenzy', 'commander', 'fanatic', 'retreat', 'surrender', 'victory'
] as const

/** What the tutorial teaches; the test checks every one shows up */
export type Lesson = typeof LESSONS[number]

interface StepBase {
  /** Panel text (key of `t().tutorial.steps`); `[text]` is highlighted */
  text?: TutorialTextKey
  /** Hexes to point at, besides the ones of the action */
  hexes?: Hex[]
  /** Units to point at (their hex and their line in the troop list) */
  units?: number[]
  ui?: TutorialUi
  lessons?: Lesson[]
}

export type TutorialStep =
  /** Text only: the player presses Next */
  | (StepBase & { kind: 'info', text: TutorialTextKey })
  /** The player must do exactly this, and the game rolls exactly these dice */
  | (StepBase & { kind: 'do', text: TutorialTextKey, action: TutorialAction, dice?: number[] })
  /** The enemy does this, with these dice */
  | (StepBase & { kind: 'cpu', action: TutorialAction, dice?: number[] })
  /** Shown while the next message in the middle of the screen (a turn or Morale tests) is open; its Continue goes on */
  | (StepBase & { kind: 'banner', on: 'turn' | 'morale', text: TutorialTextKey })

type Extra = Omit<StepBase, 'text'> & { dice?: number[] }

const info = (text: TutorialTextKey, extra: StepBase = {}): TutorialStep => ({ kind: 'info', text, ...extra })
const play = (text: TutorialTextKey, action: TutorialAction, extra: Extra = {}): TutorialStep => ({ kind: 'do', text, action, ...extra })
const cpu = (action: TutorialAction, extra: Extra = {}): TutorialStep => ({ kind: 'cpu', action, ...extra })
const banner = (on: 'turn' | 'morale', text: TutorialTextKey, extra: StepBase = {}): TutorialStep => ({ kind: 'banner', on, text, ...extra })

const move = (unit: number, to: Hex): TutorialAction => ({ a: 'move', unit, to })
const hold = (unit: number): TutorialAction => ({ a: 'hold', unit })
const shoot = (unit: number, target: number): TutorialAction => ({ a: 'shoot', unit, target })
const melee = (unit: number, target: number): TutorialAction => ({ a: 'melee', unit, target })
const first = (player: Player): TutorialAction => ({ a: 'first', player })

