/** Runs one action on the game (the scene, the scripted enemy and the test all go through here) */
export function applyAction(game: Game, action: TutorialAction): GameEvent[] {
  switch (action.a) {
  case 'first': return game.chooseFirst(action.player)
  case 'move': return game.move(action.unit, hexOf(action.to))
  case 'shoot': return game.shoot(action.unit, action.target)
  case 'hold': return game.hold(action.unit)
  case 'melee': return game.melee(action.unit, action.target)
  case 'cast': return game.cast(action.unit, action.spell, action.hex ? { hex: hexOf(action.hex) } : { unitId: action.target! })
  }
}

const sameHex = (a: Hex | undefined, b: Hex | undefined) => a?.[0] === b?.[0] && a?.[1] === b?.[1]

/** Did the player do exactly the scripted action? */
export function sameAction(expected: TutorialAction, got: TutorialAction): boolean {
  switch (expected.a) {
  case 'first': return got.a === 'first' && got.player === expected.player
  case 'move': return got.a === 'move' && got.unit === expected.unit && sameHex(got.to, expected.to)
  case 'shoot': return got.a === 'shoot' && got.unit === expected.unit && got.target === expected.target
  case 'hold': return got.a === 'hold' && got.unit === expected.unit
  case 'melee': return got.a === 'melee' && got.unit === expected.unit && got.target === expected.target
  case 'cast':
    return got.a === 'cast' && got.unit === expected.unit && got.spell === expected.spell &&
      sameHex(got.hex, expected.hex) && got.target === expected.target
  }
}

/**
 * The tutorial's dice: each step loads the dice it rolls. When they run out (only if the script and
 * the rules disagree) it rolls real dice instead of stopping the game, and remembers it.
 */
export class TutorialDice implements Dice {
  private queue: number[] = []
  /** Dice rolled beyond the loaded ones */
  extra = 0

  load(values: number[] = []) {
    this.queue = [...values]
    this.extra = 0
  }

  /** Loaded dice nobody rolled */
  get left(): number {
    return this.queue.length
  }

  d6(): number {
    const next = this.queue.shift()
    if (next !== undefined) return next
    this.extra++
    return Math.floor(Math.random() * 6) + 1
  }
}

/** A new tutorial game: map 1, both troops on their hexes, the initiative of turn 1 rolled */
export function createTutorialGame(dice: TutorialDice): Game {
  dice.load(SETUP_DICE)
  return Game.create({ map: MAP1, armies: tutorialArmies(), maxTurns: TUTORIAL_TURNS }, dice)
}

/**
 * The messages in the middle of the screen the events of one action open, in order (as the match
 * scene shows them): the Morale tests of each moment, and each new turn (after its recoveries).
 */
export function bannersOf(events: GameEvent[]): ('turn' | 'morale')[] {
  const result: ('turn' | 'morale')[] = []
  const shown = new Set<GameEvent>()
  const group = (from: number, type: 'morale-test' | 'recovery') => {
    let found = false
    for (let i = from; i < events.length; i++) {
      const e = events[i]
      if (i > from && (e.type === 'turn-end' || e.type === 'turn-start' || e.type === 'game-over')) break
      if (e.type === type && !shown.has(e)) {
        shown.add(e)
        found = true
      }
    }
    if (found) result.push('morale')
  }
  events.forEach((event, index) => {
    if (event.type === 'turn-start') {
      group(index + 1, 'recovery')
      result.push('turn')
    } else if ((event.type === 'morale-test' || event.type === 'recovery') && !shown.has(event)) {
      group(index, event.type)
    }
  })
  return result
}
