/**
 * Hex grid math (pure, no engine). Rules work on axial coordinates (q, r);
 * the board stores cells by offset coordinates (col, row), which is how the
 * map files are laid out. Pointy-top grids use "odd-r" offsets (odd rows are
 * shifted half a hex right), flat-top grids use "odd-q" (odd columns are
 * shifted half a hex down).
 *
 * Reference: https://www.redblobgames.com/grids/hexagons/
 */

export interface Axial {
  q: number
  r: number
}

export interface Offset {
  col: number
  row: number
}

export type HexOrientation = 'pointy' | 'flat'

/**
 * Hex size in pixels. `sizeX` and `sizeY` are the center-to-corner distances
 * on each axis; they differ when the hexes are stretched to fit a map drawn
 * on a square grid. Equal values give regular hexagons.
 */
export interface HexLayout {
  orientation: HexOrientation
  sizeX: number
  sizeY: number
}

export interface Point {
  x: number
  y: number
}

const SQRT3 = Math.sqrt(3)

/** The six directions, clockwise from east (pointy) or from north-east (flat) */
export const HEX_DIRECTIONS: readonly Axial[] = [
  { q: 1, r: 0 },
  { q: 0, r: 1 },
  { q: -1, r: 1 },
  { q: -1, r: 0 },
  { q: 0, r: -1 },
  { q: 1, r: -1 }
]

export const hexKey = (hex: Axial) => `${hex.q},${hex.r}`

export const hexEquals = (a: Axial, b: Axial) => a.q === b.q && a.r === b.r

export function hexAdd(hex: Axial, other: Axial): Axial {
  return { q: hex.q + other.q, r: hex.r + other.r }
}

export function hexNeighbor(hex: Axial, direction: number): Axial {
  return hexAdd(hex, HEX_DIRECTIONS[((direction % 6) + 6) % 6])
}

export function hexNeighbors(hex: Axial): Axial[] {
  return HEX_DIRECTIONS.map(d => hexAdd(hex, d))
}

/** Direction index (0-5) of an adjacent hex, or -1 when `to` is not next to `from` */
export function hexDirection(from: Axial, to: Axial): number {
  return HEX_DIRECTIONS.findIndex(d => from.q + d.q === to.q && from.r + d.r === to.r)
}

/** Number of steps between two hexes */
export function hexDistance(a: Axial, b: Axial): number {
  const dq = a.q - b.q
  const dr = a.r - b.r
  return (Math.abs(dq) + Math.abs(dr) + Math.abs(dq + dr)) / 2
}

/** Hexes at exactly `radius` steps from `center` (the center itself when radius is 0) */
export function hexRing(center: Axial, radius: number): Axial[] {
  if (radius <= 0) return radius === 0 ? [center] : []
  const result: Axial[] = []
  // start at the hex `radius` steps in direction 4, then walk the six sides
  let hex = { q: center.q + HEX_DIRECTIONS[4].q * radius, r: center.r + HEX_DIRECTIONS[4].r * radius }
  for (let side = 0; side < 6; side++) {
    for (let step = 0; step < radius; step++) {
      result.push(hex)
      hex = hexNeighbor(hex, side)
    }
  }
  return result
}

/** Every hex within `radius` steps of `center`, the center included */
export function hexRange(center: Axial, radius: number): Axial[] {
  const result: Axial[] = []
  for (let q = -radius; q <= radius; q++) {
    for (let r = Math.max(-radius, -q - radius); r <= Math.min(radius, -q + radius); r++) {
      result.push({ q: center.q + q, r: center.r + r })
    }
  }
  return result
}

/** Rounds fractional axial coordinates to the hex that contains them */
export function hexRound(q: number, r: number): Axial {
  const s = -q - r
  let rq = Math.round(q)
  let rr = Math.round(r)
  const rs = Math.round(s)
  const dq = Math.abs(rq - q)
  const dr = Math.abs(rr - r)
  const ds = Math.abs(rs - s)
  if (dq > dr && dq > ds) rq = -rr - rs
  else if (dr > ds) rr = -rq - rs
  // `+ 0` turns -0 into 0
  return { q: rq + 0, r: rr + 0 }
}

/**
 * Hexes on the straight line from `a` to `b`, both included (line of sight).
 * A tiny nudge keeps lines that run exactly along a hex edge deterministic.
 */
export function hexLine(a: Axial, b: Axial): Axial[] {
  const n = hexDistance(a, b)
  if (n === 0) return [{ q: a.q, r: a.r }]
  const result: Axial[] = []
  for (let i = 0; i <= n; i++) {
    const t = i / n
    result.push(hexRound(
      a.q + (b.q - a.q) * t + 1e-6,
      a.r + (b.r - a.r) * t + 2e-6
    ))
  }
  return result
}

/** Axial coordinates of the cell at (col, row) */
export function offsetToAxial(col: number, row: number, orientation: HexOrientation): Axial {
  if (orientation === 'pointy') return { q: col - (row - (row & 1)) / 2, r: row }
  return { q: col, r: row - (col - (col & 1)) / 2 }
}

/** Offset (col, row) of an axial hex */
export function axialToOffset(hex: Axial, orientation: HexOrientation): Offset {
  if (orientation === 'pointy') return { col: hex.q + (hex.r - (hex.r & 1)) / 2, row: hex.r }
  return { col: hex.q, row: hex.r + (hex.q - (hex.q & 1)) / 2 }
}

/** Pixel position of the center of `hex` (hex (0, 0) is at the origin) */
export function hexToPixel(hex: Axial, layout: HexLayout): Point {
  if (layout.orientation === 'pointy') {
    return { x: layout.sizeX * SQRT3 * (hex.q + hex.r / 2), y: layout.sizeY * 1.5 * hex.r }
  }
  return { x: layout.sizeX * 1.5 * hex.q, y: layout.sizeY * SQRT3 * (hex.r + hex.q / 2) }
}

/** The hex that contains a pixel position (inverse of `hexToPixel`) */
export function pixelToHex(point: Point, layout: HexLayout): Axial {
  const x = point.x / layout.sizeX
  const y = point.y / layout.sizeY
  if (layout.orientation === 'pointy') return hexRound((SQRT3 / 3) * x - y / 3, (2 / 3) * y)
  return hexRound((2 / 3) * x, (-1 / 3) * x + (SQRT3 / 3) * y)
}

/** Way a sprite looks: the four sides of a unit sheet (left/right are the same art, mirrored) */
export type Facing = 'up' | 'down' | 'left' | 'right'

/**
 * Side a sprite turns to when looking from `from` to `to` (any two hexes),
 * by their pixel positions: mostly sideways looks left/right, else up/down.
 * Pure geometry on the real (unmirrored) board.
 */
export function hexFacing(from: Axial, to: Axial, layout: HexLayout): Facing {
  const a = hexToPixel(from, layout)
  const b = hexToPixel(to, layout)
  const dx = b.x - a.x
  const dy = b.y - a.y
  if (Math.abs(dx) >= Math.abs(dy)) return dx >= 0 ? 'right' : 'left'
  return dy < 0 ? 'up' : 'down'
}

/** The six corners of a hex centered on the origin, clockwise */
export function hexCorners(layout: HexLayout): Point[] {
  const start = layout.orientation === 'pointy' ? 30 : 0
  return [0, 1, 2, 3, 4, 5].map(i => {
    const angle = ((start + 60 * i) * Math.PI) / 180
    return { x: layout.sizeX * Math.cos(angle), y: layout.sizeY * Math.sin(angle) }
  })
}
