/**
 * The CPU player of ONAGRO. Pure (only talks to a `Game`), so it can play
 * without graphics: `yarn onagro:sim` pits levels against each other.
 *
 * How it thinks (one activation at a time, with the exact odds of the engine):
 * - every option of a unit is worth what it gains minus what it risks:
 *     gain  = expected PV taken from the enemy x their worth, plus kills (and the points they give)
 *     risk  = expected PV the enemy can take back next turn where the unit ends up
 * - the options are: hold, shoot (never after moving: one action per activation), cast, or move
 *   somewhere (next to an enemy it fights in the melee phase: both sides hit)
 * - the unit with the most to gain from acting goes first, so shooters thin the enemy
 *   before the others walk into its range
 * - melee: pick the fight that hurts most, and kill what has not fought yet before it does
 * It never needs to "know" a rule: it only asks the game what is legal and what the odds are.
 */
import { Axial, hexDistance, hexNeighbors, hexRange } from '../hex'
import { Game, GameEvent } from './game'
import { chanceAtLeast, forecastStrike, hitChance, targetNumber } from './combat'
import { SPELLS, chance2d6AtLeast } from './spells'
import { inMap, lineOfSight, terrainAt } from './terrain'
import { Player, SpellId, UnitState, abilityOf, inPlay, pointsOf } from './units'

export type AiLevel = 'easy' | 'normal' | 'hard'

export const AI_LEVELS: AiLevel[] = ['easy', 'normal', 'hard']

export interface AiOptions {
  level?: AiLevel
  /** Randomness of the mistakes and noise (default Math.random); pass a seeded one in simulations */
  random?: () => number
}

interface LevelSettings {
  /** Random noise added to every option, in "worth" units */
  noise: number
  /** Chance to take the second best option */
  mistake: number
  /** How much it fears the enemy */
  fear: number
}

/**
 * The levels differ in mistakes, not in knowledge. In simulations every level beats the stand-in baseline,
 * and the gaps between levels are small next to the luck of the dice (60 games are worth about +-7%).
 */
export const LEVEL_SETTINGS: Record<AiLevel, LevelSettings> = {
  easy: { noise: 2.2, mistake: 0.5, fear: 0.2 },
  normal: { noise: 0.2, mistake: 0.08, fear: 1 },
  hard: { noise: 0.04, mistake: 0, fear: 1 }
}

/**
 * Weights of the AI, tuned with `yarn onagro:sim` (change them there first):
 * - approach: worth per hex closer to the enemy for units that fight in melee
 * - sees: bonus for a hex from which shooters or casters can reach an enemy
 * - boldness: how much the growing aggression (late turns, being behind) shrinks the fear of the enemy
 */
export const TUNING = { approach: 0.35, sees: 0.45, boldness: 1 }

/** Does the AI activate second when it holds the initiative? (the second player answers what the first did) */
export const PREFERS_SECOND = true

export type CpuMove = () => GameEvent[]

/** The next thing `player` does when the game waits for them, or null when it is not their turn */
export function cpuMove(game: Game, player: Player, options: AiOptions = {}): CpuMove | null {
  const { state } = game
  const ai = new Brain(game, player, options)
  if (state.phase === 'initiative') return state.initiative === player ? ai.initiative() : null
  if (state.phase === 'activation') return state.activePlayer === player ? ai.activation() : null
  if (state.phase === 'melee') return state.melee.next === player ? ai.melee() : null
  return null
}

const key = (hex: Axial) => `${hex.q},${hex.r}`
const clamp = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value))

/** How much a unit is worth to its side: its cost in units of 50 points, and the commander more */
const worth = (unit: UnitState) => unit.sheet.points / 50 + (unit.commander ? 1.5 : 0)
const perPv = (unit: UnitState) => worth(unit) / unit.sheet.stats.pv
/** What losing the unit costs besides its PV: its worth and the points the enemy scores */
const lossOf = (unit: UnitState) => worth(unit) + pointsOf(unit)

interface Option {
  kind: 'hold' | 'shoot' | 'cast' | 'move'
  score: number
  run: CpuMove
  /** Worth gained by the action itself, apart from where it leaves the unit */
  gain: number
}

interface Threat {
  melee: Set<string> | null
  shot: Set<string> | null
  spell: Set<string> | null
  /** Hexes a damaging spell aimed at one enemy (Aflição) reaches, and the PV it takes on average there */
  curse: Set<string> | null
  curseDamage: number
}

class Brain {
  private readonly level: LevelSettings
  private readonly random: () => number
  private readonly enemies: UnitState[]
  private readonly threats = new Map<number, Threat>()
  private readonly lastTurn: boolean
  private readonly aggression: number

  constructor(private readonly game: Game, private readonly player: Player, options: AiOptions) {
    this.level = LEVEL_SETTINGS[options.level ?? 'normal']
    this.random = options.random ?? Math.random
    const { state } = game
    this.enemies = state.units.filter(u => inPlay(u) && u.owner !== player)
    this.lastTurn = state.turn >= state.maxTurns
    const [mine, theirs] = player === 0 ? game.scores() : [game.scores()[1], game.scores()[0]]
    const behind = mine < theirs
    // bolder as the game runs out, and when behind on points
    this.aggression = (1 + 0.18 * (state.turn - 1)) * (behind && state.turn >= 3 ? 1.35 : 1) * (this.lastTurn ? 1.6 : 1)
  }

  // --------------------------------------------------------- initiative

  initiative(): CpuMove {
    const first = PREFERS_SECOND ? (this.player === 0 ? 1 : 0) : this.player
    return () => this.game.chooseFirst(first)
  }

  // --------------------------------------------------------- activation

  activation(): CpuMove {
    const { game } = this
    const current = game.state.current
    const candidates = current ? [game.unit(current.unitId)] : game.pendingActivations(this.player)
    const choices: { unit: UnitState, option: Option, delta: number }[] = []
    for (const unit of candidates) {
      const options = this.options(unit)
      const choice = this.pick(options)
      choices.push({ unit, option: choice, delta: choice.score - options[0].score })
    }
    // whoever can shoot or cast acts first (it thins the enemy before the others walk), then the one with the most to gain
    const attacks = choices.filter(c => c.option.kind === 'shoot' || c.option.kind === 'cast')
    const pool = attacks.length > 0 ? attacks : choices
    const best = pool.reduce((top, c) => (c.delta > top.delta || (c.delta === top.delta && c.unit.id < top.unit.id) ? c : top))
    if (!best) throw new Error('Nothing to activate')
    return best.option.run
  }

  /** The best option, with the level's noise and mistakes */
  private pick(options: Option[]): Option {
    const noisy = options.map(o => ({ o, s: o.score + (this.level.noise > 0 ? (this.random() - 0.5) * 2 * this.level.noise : 0) }))
    noisy.sort((a, b) => b.s - a.s)
    if (this.level.mistake > 0 && noisy.length > 1 && this.random() < this.level.mistake) return noisy[1].o
    return noisy[0].o
  }

  /** Every legal thing the unit could do now, first of them "hold" */
  private options(unit: UnitState): Option[] {
    const { game } = this
    const current = game.state.current
    const engaged = game.isEngaged(unit.id)
    const options: Option[] = []
    // shooting and casting leave the unit where it is: what staying is worth counts too
    const hereRisk = this.risk(unit, unit.pos!) - this.position(unit, unit.pos!)

    const stay = engaged ? this.engagement(unit, unit.pos!) : 0
    options.push({ kind: 'hold', gain: 0, score: stay - hereRisk, run: () => game.hold(unit.id) })

    if (!engaged && unit.sheet.ranged && (!current || current.kind === 'shoot')) {
      for (const target of game.shootTargets(unit.id)) {
        const f = game.forecastShot(unit.id, target.id)
        if (!f.inRange) continue
        const gain = f.expectedDamage * perPv(target) + f.killChance * lossOf(target) - this.friendlyFire(unit, target, f.hitChance * (1 - f.enemyChance))
        options.push({ kind: 'shoot', gain, score: gain - hereRisk, run: () => game.shoot(unit.id, target.id) })
      }
    }

    if (!engaged && (!current || current.kind === 'cast')) {
      for (const spell of unit.sheet.spells) {
        if (current?.spells.includes(spell) || !game.spellReady(unit.id, spell)) continue
        options.push(...this.spellOptions(unit, spell, hereRisk))
      }
    }

    if (!current) {
      const range = game.reachable(unit.id).range
      const freeAttack = engaged ? this.freeAttackCost(unit) : 0
      for (const hex of range) {
        const gain = this.engagement(unit, hex)
        options.push({
          kind: 'move',
          gain,
          score: gain + this.position(unit, hex) - this.risk(unit, hex) - freeAttack,
          run: () => game.move(unit.id, hex)
        })
      }
    }
    return options
  }

  private spellOptions(unit: UnitState, spell: SpellId, hereRisk: number): Option[] {
    const { game } = this
    const def = SPELLS[spell]
    const result: Option[] = []
    if (def.kind === 'area') {
      const centers = new Map<string, Axial>()
      for (const enemy of this.enemies) {
        centers.set(key(enemy.pos!), enemy.pos!)
        for (const n of hexNeighbors(enemy.pos!)) centers.set(key(n), n)
      }
      for (const hex of centers.values()) {
        if (!inMap(game.state.map, hex) || hexDistance(unit.pos!, hex) > def.range || !lineOfSight(game.state.map, unit.pos!, hex)) continue
        let gain = 0
        for (const hit of game.forecastSpell(spell, hex)) {
          const value = hit.strike.expectedDefenderDamage * perPv(hit.unit) + hit.killChance * lossOf(hit.unit)
          gain += hit.unit.owner === unit.owner ? -1.3 * value : value
        }
        if (gain > 0) result.push({ kind: 'cast', gain, score: gain - hereRisk, run: () => game.cast(unit.id, spell, { hex }) })
      }
    } else if (def.heal) {
      for (const ally of game.unitsOf(unit.owner)) {
        if (ally.hp >= ally.sheet.stats.pv || hexDistance(unit.pos!, ally.pos!) > def.range) continue
        const gain = perPv(ally) * (1 + (ally.hp <= 1 ? 0.6 : 0)) * 0.9
        result.push({ kind: 'cast', gain, score: gain - hereRisk, run: () => game.cast(unit.id, spell, { unitId: ally.id }) })
      }
    } else if (def.kind === 'enemy') {
      // Aflição takes PV past any PD; Medo is worth part of the enemy (it backs off, -1 on its dice, may break)
      for (const enemy of this.enemies) {
        if (!game.canCurse(spell, enemy.id)) continue
        const f = game.forecastCurse(unit.id, spell, enemy.id)
        if (!f.inRange || !f.inSight || f.chance === 0) continue
        let gain = f.expectedDamage * perPv(enemy) + f.killChance * lossOf(enemy)
        if (def.morale) gain += f.chance * worth(enemy) * (enemy.moraleFailures > 0 ? 0.55 : 0.3)
        result.push({ kind: 'cast', gain, score: gain - hereRisk, run: () => game.cast(unit.id, spell, { unitId: enemy.id }) })
      }
    } else if (def.kind === 'raise') {
      const fallen = game.raisable(unit.owner)[0]
      if (!fallen) return result
      // back in play: the enemy loses the point, and the unit is worth its cost again; the hex nearest the enemy
      let best: Axial | null = null
      let bestScore = -Infinity
      for (const hex of hexRange(unit.pos!, def.range)) {
        const terrain = terrainAt(game.state.map, hex)
        if (!terrain || terrain.move === 'blocked' || game.unitAt(hex)) continue
        const near = this.enemies.length > 0 ? Math.min(...this.enemies.map(e => hexDistance(e.pos!, hex))) : 0
        const score = (fallen.sheet.ranged ? -Math.abs(near - 6) : -near) - (near <= 1 ? 2 : 0)
        if (score > bestScore) {
          bestScore = score
          best = hex
        }
      }
      if (!best) return result
      const hex = best
      const gain = lossOf(fallen)
      result.push({ kind: 'cast', gain, score: gain - hereRisk, run: () => game.cast(unit.id, spell, { hex }) })
    } else if (def.shieldPd) {
      // a shield on whoever is about to be hit hardest
      for (const ally of game.unitsOf(unit.owner)) {
        if (ally.shield || hexDistance(unit.pos!, ally.pos!) > def.range) continue
        const gain = this.risk(ally, ally.pos!) * 0.35
        if (gain > 0.1) result.push({ kind: 'cast', gain, score: gain - hereRisk, run: () => game.cast(unit.id, spell, { unitId: ally.id }) })
      }
    }
    return result
  }

  /**
   * Worth the shooter expects to take from its own side when the target is engaged with allies
   * ("Fogo amigo": a hit lands on one of them with `chance`), weighed like allies under an area spell
   */
  private friendlyFire(shooter: UnitState, target: UnitState, chance: number): number {
    if (chance <= 0) return 0
    const { game } = this
    const allies = game.adjacentEnemies(target.id).filter(ally => ally.id !== shooter.id)
    let worth = 0
    for (const ally of allies) {
      const strike = game.forecastShot(shooter.id, ally.id).strike
      worth += (strike.expectedDefenderDamage * perPv(ally) + chanceAtLeast(strike.defenderDamage, ally.hp) * lossOf(ally)) / allies.length
    }
    return 1.3 * chance * worth
  }

  // --------------------------------------------------------------- melee

  melee(): CpuMove {
    const { game, player } = this
    const pending = new Set(game.state.melee.pending)
    let best: { unit: number, target: number, score: number } | null = null
    for (const unit of game.meleeChoices(player)) {
      for (const target of game.meleeTargets(unit.id)) {
        const f = game.forecastMelee(unit.id, target.id)
        const attacks = game.attacksOf(unit.id)
        let score = attacks * f.strike.expectedDefenderDamage * perPv(target) * (target.commander ? 1.2 : 1) + f.killChance * lossOf(target)
        score -= attacks * f.strike.expectedAttackerDamage * perPv(unit) + f.backlashKillChance * lossOf(unit)
        // killing someone who has not fought yet also saves what it would have done to us
        if (pending.has(target.id) && game.canFight(target.id)) {
          const back = game.forecastMelee(target.id, unit.id)
          score += f.killChance * game.attacksOf(target.id) * back.strike.expectedDefenderDamage * perPv(unit)
        }
        score += (this.random() - 0.5) * 2 * this.level.noise
        if (!best || score > best.score) best = { unit: unit.id, target: target.id, score }
      }
    }
    const choice = best
    if (!choice) throw new Error('No melee to fight')
    return () => game.melee(choice.unit, choice.target)
  }

  // ---------------------------------------------------------- valuation

  /** Worth the unit would gain by fighting the best adjacent enemy of `hex` in the melee phase */
  private engagement(unit: UnitState, hex: Axial): number {
    const { game } = this
    let best = 0
    for (const n of hexNeighbors(hex)) {
      const enemy = game.unitAt(n)
      if (!enemy || enemy.owner === unit.owner || !inPlay(enemy)) continue
      const f = game.forecastMelee(unit.id, enemy.id)
      const attacks = game.attacksOf(unit.id)
      const value = attacks * f.strike.expectedDefenderDamage * perPv(enemy) + f.killChance * lossOf(enemy)
        - attacks * f.strike.expectedAttackerDamage * perPv(unit)
      best = Math.max(best, value)
    }
    return best * (this.lastTurn ? 1.4 : 1)
  }

  /** Worth lost to the free attack of the strongest enemy next to a unit that walks away */
  private freeAttackCost(unit: UnitState): number {
    const { game } = this
    let worst = 0
    for (const enemy of game.adjacentEnemies(unit.id)) {
      const f = game.forecastMelee(enemy.id, unit.id)
      worst = Math.max(worst, f.strike.expectedDefenderDamage * perPv(unit) + f.killChance * lossOf(unit))
    }
    return worst * this.level.fear
  }

  /** Where the unit would like to be, apart from fighting and danger */
  private position(unit: UnitState, hex: Axial): number {
    if (this.enemies.length === 0 || this.lastTurn) return 0
    const { game } = this
    const nearest = Math.min(...this.enemies.map(e => hexDistance(e.pos!, hex)))
    const ranged = unit.sheet.ranged
    const attackSpells = unit.sheet.spells.filter(s => SPELLS[s].kind === 'area' || SPELLS[s].kind === 'enemy')
    const caster = attackSpells.length > 0
    let score = 0
    if (ranged || caster) {
      const reach = ranged?.range ?? Math.max(...attackSpells.map(s => SPELLS[s].range))
      const sees = this.enemies.some(e => hexDistance(e.pos!, hex) <= reach && lineOfSight(game.state.map, hex, e.pos!))
      score += sees ? TUNING.sees * this.aggression : -0.1 * Math.min(nearest, 14) * this.aggression
      const cover = terrainAt(game.state.map, hex)?.cover
      score += cover === 'heavy' ? 0.25 : cover === 'light' ? 0.12 : 0
    } else {
      score -= TUNING.approach * Math.min(nearest, 16) * this.aggression
    }
    // commanders and leaders of auras like to keep their troop around them
    const aura = unit.sheet.abilities.find(a => a.id === 'inspiration' || a.id === 'war-song')
    if (aura) {
      const near = game.unitsOf(unit.owner).filter(a => a !== unit && hexDistance(a.pos!, hex) <= (aura.radius ?? 0)).length
      score += 0.07 * near
    }
    return score
  }

  /** Worth the unit is expected to lose if it ends its turn on `hex` (what the enemy can do next) */
  private risk(unit: UnitState, hex: Axial): number {
    const { game } = this
    const { dice: defense, bonus: defenseBonus } = game.defenseOf(unit.id)
    const block = !!abilityOf(unit.sheet, 'block')
    const cover = terrainAt(game.state.map, hex)?.cover ?? 'none'
    const damages: number[] = []
    for (const enemy of this.enemies) {
      if (enemy.moraleFailures >= 2) continue // retreating or surrendering: no threat
      const threat = this.threatOf(enemy)
      const k = key(hex)
      let expected = 0
      if (threat.melee?.has(k)) {
        const f = forecastStrike({
          attackDice: enemy.sheet.stats.pa, defenseDice: defense, defenseBonus, melee: true,
          mods: { rerollHighest: block, fury: !!abilityOf(enemy.sheet, 'fury'), shaken: enemy.moraleFailures === 1 }
        })
        expected += f.expectedDefenderDamage * game.attacksOf(enemy.id)
      }
      if (threat.shot?.has(k) && enemy.sheet.ranged) {
        const weapon = enemy.sheet.ranged
        const hit = hitChance(targetNumber(weapon.ra, enemy.sheet.hitBonus ?? 0, cover))
        const f = forecastStrike({ attackDice: weapon.pa, defenseDice: defense, defenseBonus, melee: false, mods: { rerollHighest: block, fury: !!abilityOf(enemy.sheet, 'fury'), shaken: false } })
        expected += hit * f.expectedDefenderDamage * enemy.sheet.stats.a
      }
      if (threat.spell?.has(k)) {
        const best = Math.max(...enemy.sheet.spells.map(s => SPELLS[s].pa ?? 0))
        if (best > 0) {
          const f = forecastStrike({ attackDice: best, defenseDice: defense, defenseBonus, melee: false, mods: { rerollHighest: block, fury: false, shaken: false } })
          expected += f.expectedDefenderDamage
        }
      }
      // Aflição: PV lost past any PD when the save fails
      if (threat.curse?.has(k)) expected += threat.curseDamage
      if (expected > 0) damages.push(expected)
    }
    damages.sort((a, b) => b - a)
    const sum = damages.slice(0, 3).reduce((a, b) => a + b, 0)
    if (sum === 0) return 0
    const lost = Math.min(sum, unit.hp)
    const dies = clamp((sum - 0.35 * unit.hp) / (unit.hp * 1.2), 0, 1)
    return (lost * perPv(unit) + dies * lossOf(unit)) * this.level.fear / this.aggression ** TUNING.boldness
  }

  /** The hexes an enemy can hurt next turn: in melee after moving, by a shot or a spell from where it stands */
  private threatOf(enemy: UnitState): Threat {
    const known = this.threats.get(enemy.id)
    if (known) return known
    const { game } = this
    const engaged = game.isEngaged(enemy.id)
    const melee = new Set<string>()
    const starts = [enemy.pos!, ...game.reachable(enemy.id).range]
    for (const start of starts) for (const n of hexNeighbors(start)) melee.add(key(n))
    let shot: Set<string> | null = null
    const weapon = enemy.sheet.ranged
    if (weapon && !engaged) shot = this.visibleWithin(enemy.pos!, weapon.range)
    let spell: Set<string> | null = null
    if (!engaged) {
      for (const id of enemy.sheet.spells) {
        const def = SPELLS[id]
        if (def.kind !== 'area' || !game.spellReady(enemy.id, id)) continue
        spell = spell ?? new Set()
        // the area also covers the 6 hexes around the center, so one hex farther
        for (const hex of this.visibleWithin(enemy.pos!, def.range)) {
          spell.add(hex)
          const [q, r] = hex.split(',').map(Number)
          for (const n of hexNeighbors({ q, r })) spell.add(key(n))
        }
      }
    }
    let curse: Set<string> | null = null
    let curseDamage = 0
    if (!engaged) {
      for (const id of enemy.sheet.spells) {
        const def = SPELLS[id]
        if (def.kind !== 'enemy' || !def.damage || !game.spellReady(enemy.id, id)) continue
        curse = this.visibleWithin(enemy.pos!, def.range)
        curseDamage = Math.max(curseDamage, def.damage * (1 - chance2d6AtLeast(def.save ?? 2)))
      }
    }
    const threat = { melee, shot, spell, curse, curseDamage }
    this.threats.set(enemy.id, threat)
    return threat
  }

  private visibleWithin(from: Axial, range: number): Set<string> {
    const { map } = this.game.state
    const result = new Set<string>()
    for (const hex of hexRange(from, range)) {
      if (hex.q === from.q && hex.r === from.r) continue
      if (terrainAt(map, hex) && lineOfSight(map, from, hex)) result.add(key(hex))
    }
    return result
  }
}
