export const ONAGRO_SCENE = 'onagro'

/**
 * Chosen on the start screen before the match (mode, map, then each side's troop and
 * deployment). Side 0 is player 1 (the left rail), side 1 the CPU or player 2.
 */
export interface MatchOptions {
  /** The sides the AI plays: [1] against a player, [] two players share the screen, [0, 1] AI vs AI (watch) */
  cpu: Player[]
  level: AiLevel
  map: MapId
  /** The troop of each side (two different troops) */
  troops: [TroopId, TroopId]
  /** The edge of each side (opposite edges) */
  edges: [Edge, Edge]
  /** Where each unit of each troop starts, in the order of the troop's units */
  placements: [Axial[], Axial[]]
  /** The guided match (src/tutorial/): map 1, Humans against the scripted Undead; the rest of the options is ignored */
  tutorial?: boolean
}

/** The tutorial's options: map 1, the player's Humans on the west edge against the Undead on the east one, standard formation */
export function tutorialOptions(): MatchOptions {
  return { cpu: [1], level: 'normal', map: 'map1', troops: ['human', 'undead'], edges: TUTORIAL_EDGES, placements: TUTORIAL_PLACEMENTS, tutorial: true }
}

/** Size of the minis on the board */
const SPRITE_SCALE = 3.3
/** Width of the PV bar canvas: the bar in the middle, markers on both sides */
const BAR_WIDTH = 180
/** The marker tokens beside each unit: side in pixels, and the step between two in a column */
const TOKEN = 26
const TOKEN_STEP = 28
/** The canvas of the tokens, centered on the unit: a column on each side of the sprite */
const TOKENS_WIDTH = 110
const TOKENS_HEIGHT = 84
/** Pause before the CPU acts, so the player can follow */
const CPU_PAUSE = 450
/**
 * When the AI holds the initiative: how long the roll stays on screen before it chooses, and then
 * its choice before the banner closes (ms, real time whatever the game speed; Continue skips it)
 */
const BANNER_TIME = 5000
/** Between the last fall and the result of the match (ms, at x1) */
const GAME_OVER_PAUSE = 700
/** The board on its own when the match starts, before the initiative roll of turn 1 (ms, real time) */
const INTRO_PAUSE = 2000
/** The AI's path and its enemies' zone of control on screen before its unit walks (ms, at x1) */
const CPU_MOVE_PREVIEW = 700

/** The tutorial's marks on the map blink this often (ms) */
const TUTORIAL_BLINK = 450

type TurnStart = Extract<GameEvent, { type: 'turn-start' }>
type MoraleEvent = Extract<GameEvent, { type: 'morale-test' | 'recovery' }>
/** Screen pixels left around the map, between it and the HUD column and the window edges */
const MAP_GAP = 8
const GOLD = '#ffd23f'

/** A hex as the tutorial's script writes it: [column, row] */
const offsetOf = (hex: Axial): Hex => {
  const { col, row } = axialToOffset(hex, 'pointy')
  return [col, row]
}

type Mode = 'none' | 'move' | 'shoot' | 'cast'

/** Something drawn over a hex: a fill, an outline, or (with `to`) a line to the center of another hex */
interface Mark { hex: Axial, fill?: string, stroke?: string, width?: number, to?: Axial, dash?: boolean, halo?: boolean }

/** One unit on the board: a root at its hex with the ring, the sprite and the PV bar as children */
class UnitView {
  readonly root: ex.Actor
  readonly sprite: ex.Actor
  readonly bar: ex.Canvas
  private turn = 1
  private activated = false
  readonly ring: ex.Canvas
  readonly tokens: ex.Canvas
  readonly anim: ex.Animation

  constructor(readonly unit: UnitState, private readonly selectedId: () => number | null, faceLeft: boolean, color: string, at: { x: number, y: number }, side: Player = 0) {
    const { x, y } = at
    this.root = new ex.Actor({ pos: ex.vec(x, y), z: 3 })

    this.ring = new ex.Canvas({
      width: 90, height: 40, cache: true,
      draw: ctx => {
        const selected = this.selectedId() === this.unit.id
        ctx.lineWidth = selected ? 5 : 3
        ctx.strokeStyle = selected ? GOLD : color
        ctx.fillStyle = 'rgba(0,0,0,0.28)'
        ctx.beginPath()
        ctx.ellipse(45, 20, 34, 13, 0, 0, Math.PI * 2)
        ctx.fill()
        ctx.stroke()
      }
    })
    const ring = new ex.Actor({ pos: ex.vec(0, 22), z: 0 })
    ring.graphics.use(this.ring)
    this.root.addChild(ring)

    this.anim = unitAnimations(unit.sheet.id, side).idle.clone()
    this.sprite = new ex.Actor({ pos: ex.vec(0, -4), scale: ex.vec(SPRITE_SCALE, SPRITE_SCALE), z: 1 })
    this.sprite.graphics.use(this.anim)
    this.sprite.graphics.flipHorizontal = faceLeft
    this.root.addChild(this.sprite)

    this.bar = new ex.Canvas({
      width: BAR_WIDTH, height: 22, cache: true,
      draw: ctx => this.drawBar(ctx)
    })
    const bar = new ex.Actor({ pos: ex.vec(0, 40), z: 2 })
    bar.graphics.use(this.bar)
    this.root.addChild(bar)

    this.tokens = new ex.Canvas({
      width: TOKENS_WIDTH, height: TOKENS_HEIGHT, cache: true,
      draw: ctx => this.drawTokens(ctx)
    })
    const tokens = new ex.Actor({ pos: ex.vec(0, -8), z: 3 })
    tokens.graphics.use(this.tokens)
    this.root.addChild(tokens)
  }

  /**
   * The guide's markers as tokens: who the unit is and how it stands on the left (commander,
   * Moral failures), what it did and what it has on the right (activated, shield, spell recharging)
   */
  private drawTokens(ctx: CanvasRenderingContext2D) {
    const { left, right } = unitMarkers(this.unit, this.activated, this.turn)
    left.forEach((marker, i) => drawToken(ctx, marker, 2, i * TOKEN_STEP, TOKEN))
    right.forEach((marker, i) => drawToken(ctx, marker, TOKENS_WIDTH - TOKEN - 2, i * TOKEN_STEP, TOKEN))
  }

  private drawBar(ctx: CanvasRenderingContext2D) {
    const { unit } = this
    const max = unit.sheet.stats.pv
    const gap = 3
    const width = Math.min(18, (86 - gap * (max - 1)) / max)
    const total = max * width + (max - 1) * gap
    const left = (BAR_WIDTH - total) / 2
    ctx.fillStyle = '#000'
    ctx.fillRect(left - 3, 3, total + 6, 15)
    for (let i = 0; i < max; i++) {
      ctx.fillStyle = i < unit.hp ? (unit.hp <= max / 3 ? '#ff4d4d' : unit.hp < max ? '#ffd23f' : '#4ee06a') : '#3a3a3a'
      ctx.fillRect(left + i * (width + gap), 6, width, 9)
    }
  }

  /** Redraws what depends on the unit's state (`turn`: the current turn, for the spell recharge marker) */
  update(dim: boolean, turn: number) {
    this.turn = turn
    this.activated = dim
    this.bar.flagDirty()
    this.tokens.flagDirty()
    this.ring.flagDirty()
    this.anim.tint = dim ? ex.Color.Gray : ex.Color.White
  }

}

/** The ONAGRO match on map 1: local play against the stand-in CPU (or two players) */
export class OnagroScene extends ex.Scene {
  private game!: Game
  private hud: OnagroHud | null = null
  private views = new Map<number, UnitView>()
  private overlay!: ex.Canvas
  private gridActor!: ex.Actor
  private subscriptions: ex.Subscription[] = []

  private selected: number | null = null
  private mode: Mode = 'none'
  private spell: SpellId | null = null
  private hover: Axial | null = null
  private message = ''
  private logLines: string[] = []
  private showLog = false
  private showGrid = true
  /** The match menu is open: the game waits (the CPU too) */
  private menuOpen = false
  /** The Options page of the match menu (sound, fullscreen, language, combat log, grid) */
  private optionsOpen = false
  /** Stops listening to the language (it can change from the match menu) */
  private stopLanguage: (() => void) | null = null
  private quitArmed = false
  /** Chosen before the match (start screen) */
  private cpu: Player[] = [1]
  private level: AiLevel = 'normal'
  /** The troop of each side: [player 1, CPU or player 2] */
  private troops: [TroopId, TroopId] = ['human', 'orc']
  /** The edge of each side */
  private edges: [Edge, Edge] = ['west', 'east']
  private map: MapEntry = mapById('map1')
  /** Where each unit starts (chosen on the start screen) */
  private placements: [Axial[], Axial[]] = [[], []]
  private locked = false
  private driving = false
  private active = false
  private flash: Mark[] = []
  private dice: DiceView | null = null
  private diceTimer = 0
  /** The message between turns (end of the turn, initiative roll), until someone activates first */
  private banner: { ended: number | null, start: TurnStart, first: Player | null } | null = null
  /** The AI's unit walking: whose enemies' zone of control and which path to draw */
  private cpuMoving: { owner: Player, path: Axial[] } | null = null
  /** The Morale tests on screen (end of the turn, recoveries, Fear) */
  private moraleTests: MoraleEvent[] | null = null
  /** Closes the banner when the AI holds the initiative (the button, Enter, or the time running out) */
  private closeBanner: (() => void) | null = null
  /** The turn that just ended, waiting for the start of the next one to show both together */
  private endedTurn: number | null = null
  /** The game is over and its last animations played: now the result can show */
  private overShown = false
  /** The guided match: the script, what the player may do, the scripted enemy (null in a normal match) */
  private tutorial: TutorialRun | null = null
  private tutorialMode = false
  /** Waiting for the tutorial's text steps (Next works even while the game is locked) */
  private settling = false
  /** The text on the tutorial panel while the game plays something out */
  private tutorialText: TutorialTextKey | 'watch' | null = null
  private skipArmed = false
  private blink = false
  private blinkTimer = 0

  onActivate(context: ex.SceneActivationContext<MatchOptions>) {
    // the options come from the start screen; "play again" keeps the ones of this match
    if (context.data) {
      const { cpu, level, map, troops, edges, placements, tutorial } = context.data
      this.tutorialMode = !!tutorial
      this.cpu = cpu
      this.level = level
      this.map = mapById(map)
      this.troops = troops
      this.edges = edges
      this.placements = placements
    }
    this.start()
  }

  /** The name of each side's troop, in the current language (with its color when both sides field the same troop) */
  private sideNames(): [string, string] {
    const text = t().onagro
    const names = text.troops
    if (this.troops[0] !== this.troops[1]) return [names[this.troops[0]], names[this.troops[1]]]
    return [text.mirrorName(names[this.troops[0]], this.colorOf(0).team), text.mirrorName(names[this.troops[1]], this.colorOf(1).team)]
  }

  private troopOf(side: Player) {
    return TROOPS[this.troops[side]]
  }

  /** The colors of a side: blue for side A, red for side B, in its troop's shade */
  private colorOf(side: Player) {
    return sideColor(this.troops[side], side)
  }

  onDeactivate() {
    this.teardown()
  }

  // -------------------------------------------------------------- set up

  private start() {
    // the same dark ground as the HUD around the map
    this.backgroundColor = ex.Color.fromHex('#0b0e15')
    this.active = true
    this.selected = null
    this.mode = 'none'
    this.spell = null
    this.hover = null
    this.message = ''
    this.logLines = []
    this.flash = []
    this.menuOpen = false
    this.quitArmed = false
    this.showLog = false
    this.showGrid = true
    this.skipArmed = false
    this.tutorialText = null
    this.settling = false
    this.tutorial = this.tutorialMode ? new TutorialRun(() => this.refresh()) : null
    if (this.tutorial) {
      // the script is written for x1 (and the blinking marks need a redraw now and then)
      lockSpeed(1)
      this.blinkTimer = window.setInterval(() => {
        this.blink = !this.blink
        if (this.tutorialPointers().hexes.length > 0) this.overlay.flagDirty()
      }, TUTORIAL_BLINK)
    }

    const art =new ex.Actor({ pos: ex.vec(0, 0), anchor: ex.vec(0, 0), z: 0 })
    art.graphics.use(this.map.art.toSprite())
    this.add(art)

    this.gridActor = new ex.Actor({ pos: ex.vec(0, 0), anchor: ex.vec(0, 0), z: 1 })
    this.gridActor.graphics.use(this.makeGrid())
    this.add(this.gridActor)

    this.overlay = new ex.Canvas({
      width: this.map.size.width, height: this.map.size.height, cache: true,
      draw: ctx => this.drawOverlay(ctx)
    })
    const overlayActor = new ex.Actor({ pos: ex.vec(0, 0), anchor: ex.vec(0, 0), z: 2 })
    overlayActor.graphics.use(this.overlay)
    this.add(overlayActor)

    this.fitCamera()
    window.addEventListener('resize', this.fitCamera)

    const pointers = this.engine.input.pointers
    this.subscriptions.push(
      pointers.on('down', event => {
        if (event.button === ex.PointerButton.Left) void this.onClick(this.map.hexAt(event.worldPos.x, event.worldPos.y), event.pointerType === ex.PointerType.Touch || isTouchDevice())
      }),
      pointers.on('move', event => {
        const hex = this.map.hexAt(event.worldPos.x, event.worldPos.y)
        if (hex?.q === this.hover?.q && hex?.r === this.hover?.r) return
        this.hover = hex
        this.refresh()
      })
    )

    window.addEventListener('keydown', this.onKey)
    // the language can change from the Options of the match menu: the HUD follows at once
    this.stopLanguage = onLanguageChange(() => this.refresh())

    this.hud = document.createElement('onagro-hud')
    document.body.appendChild(this.hud)
    this.hud.addEventListener('pick-action', event => this.onPick((event as CustomEvent).detail))
    this.hud.addEventListener('hold', () => void this.onHold())
    this.hud.addEventListener('choose-first', event => void this.act({ a: 'first', player: (event as CustomEvent).detail }))
    this.hud.addEventListener('tutorial-next', () => this.tutorialNext())
    this.hud.addEventListener('tutorial-skip', () => {
      if (this.skipArmed) void this.leave()
      else {
        this.skipArmed = true
        this.refresh()
      }
    })
    this.hud.addEventListener('dismiss-banner', () => this.closeBanner?.())
    this.hud.addEventListener('open-menu', () => this.setMenu(true))
    this.hud.addEventListener('close-menu', () => this.setMenu(false))
    this.hud.addEventListener('open-options', () => this.setOptions(true))
    this.hud.addEventListener('close-options', () => this.setOptions(false))
    this.hud.addEventListener('toggle-log', () => {
      this.showLog = !this.showLog
      this.refresh()
    })
    this.hud.addEventListener('toggle-grid', () => {
      this.showGrid = !this.showGrid
      this.gridActor.graphics.isVisible = this.showGrid
      this.refresh()
    })
    // the second click leaves the match: one stray click must not throw a game away
    this.hud.addEventListener('quit', () => {
      if (this.quitArmed) void this.leave()
      else {
        this.quitArmed = true
        this.refresh()
      }
    })
    this.hud.addEventListener('again', () => this.tutorialMode ? this.realMatch() : this.restart())
    this.hud.addEventListener('menu', () => void this.leave())
    this.hud.addEventListener('pick-unit', event => this.pickUnit((event as CustomEvent).detail))
    this.hud.addEventListener('hover-unit', event => this.hoverUnit((event as CustomEvent).detail))

    MatchMusic.start()
    this.startBattle()
  }

  // ----------------------------------------------------------- camera

  /**
   * The map never moves: centered on the screen, as big as fits whole between the HUD rails
   * (`HUD_RAIL` on each side) and bands (`HUD_BAND` above and below), so the HUD never
   * covers a hex. Recomputed when the window changes size.
   */
  private fitCamera = () => {
    const { width, height } = this.engine.screen.resolution
    const canvas = this.engine.canvas.getBoundingClientRect()
    if (canvas.width === 0 || canvas.height === 0) return
    // the HUD is measured in CSS pixels from the window's edges; the canvas may be letterboxed
    const scale = hudScale()
    const rail = Math.max(HUD_RAIL * scale - canvas.left, HUD_RAIL * scale - (window.innerWidth - canvas.right), 0)
    // the tutorial's panel takes a band of its own under the map
    const top = Math.max(HUD_BAND * scale - canvas.top, 0) * height / canvas.height
    const below = HUD_BAND + (this.tutorialMode ? HUD_TUTORIAL : 0)
    const bottom = Math.max(below * scale - (window.innerHeight - canvas.bottom), 0) * height / canvas.height
    const free = {
      width: width - 2 * rail * width / canvas.width - 2 * MAP_GAP,
      height: height - top - bottom - 2 * MAP_GAP
    }
    this.camera.zoom = Math.min(free.width / this.map.size.width, free.height / this.map.size.height)
    // centered in the room between the bands: shifted up when the band below is the taller one
    this.camera.pos = ex.vec(this.map.size.width / 2, this.map.size.height / 2 - (top - bottom) / 2 / this.camera.zoom)
  }

  // ------------------------------------------------------------ units

  /** Sprites look toward the enemy: left when the side starts on the right edge */
  private faceLeft(owner: Player): boolean {
    const edge = this.edges[owner]
    return edge === 'east' || (edge !== 'west' && owner === 1)
  }

  /** Puts a sprite on the board for each unit with a position (and only for those) */
  private showUnits(units: UnitState[]) {
    for (const view of this.views.values()) view.root.kill()
    this.views.clear()
    for (const unit of units) {
      if (!unit.pos) continue
      const view = new UnitView(unit, () => this.selected, this.faceLeft(unit.owner), this.colorOf(unit.owner).hex, this.map.hexPixel(unit.pos!), unit.owner)
      this.views.set(unit.id, view)
      this.add(view.root)
    }
  }

  /** The troops on the hexes chosen before the match: the game starts (initiative of turn 1) */
  private startBattle() {
    const armies = ([0, 1] as Player[]).map(side => this.troopOf(side).units.map((sheet, i) => ({
      sheet,
      pos: this.placements[side][i],
      commander: sheet === this.troopOf(side).commander
    }))) as [Placement[], Placement[]]
    this.selected = null
    this.message = ''
    this.banner = null
    this.closeBanner = null
    this.endedTurn = null
    this.overShown = false
    this.cpuMoving = null
    // the tutorial's game rolls the script's dice
    this.game = this.tutorial ? createTutorialGame(this.tutorial.dice) : Game.create({ map: this.map.data, armies }, randomDice)
    this.showUnits(this.game.state.units)
    this.addLog(this.game.state.log)
    this.refresh()
    void this.intro()
  }

  /** The initiative roll of turn 1, in the middle of the screen, before anyone plays */
  private async intro() {
    const start = this.game.state.log.find((event): event is TurnStart => event.type === 'turn-start')
    if (start) {
      this.locked = true
      try {
        // a moment to see the board and the troops before the initiative roll (the tutorial talks first instead)
        if (!this.tutorial) await new Promise(resolve => window.setTimeout(resolve, INTRO_PAUSE))
        if (this.active) await this.announceTurn(start)
      } finally {
        this.locked = false
      }
    }
    if (!this.active) return
    this.refresh()
    void this.drive()
  }

  /**
   * The end of the turn and the initiative roll in the middle of the screen. A person holding the
   * initiative chooses there who activates first (the banner stays until then); when it is the AI,
   * the banner closes by itself after a moment, or with a click.
   */
  private async announceTurn(start: TurnStart) {
    // the tutorial's texts before it come first
    await this.settleTutorial()
    if (!this.active) return
    this.banner = { ended: this.endedTurn, start, first: null }
    this.endedTurn = null
    playSound(Resources.DiceSound)
    if (!this.isCpu(start.initiative)) {
      this.refresh()
      return
    }
    // the AI chooses at once, so the roll and its choice show together on one banner
    const events = await this.cpuChooseFirst(start.initiative)
    const first = events.find((event): event is Extract<GameEvent, { type: 'first-player' }> => event.type === 'first-player')
    this.banner = { ...this.banner, first: first?.player ?? null }
    this.addLog(events)
    await this.holdBanner('turn')
    this.banner = null
    if (!this.active) return
    this.refresh()
    // whatever the choice set off (retreating units go by themselves)
    await this.animate(events)
  }

  /** The Morale tests in the middle of the screen, until Continue or the time runs out (each shown once) */
  private async showMorale(events: GameEvent[], shown: Set<GameEvent>) {
    const tests = events.filter((event): event is MoraleEvent => (event.type === 'morale-test' || event.type === 'recovery') && !shown.has(event))
    if (tests.length === 0 || !this.active) return
    tests.forEach(event => shown.add(event))
    await this.settleTutorial()
    if (!this.active) return
    this.moraleTests = tests
    playSound(Resources.DiceSound)
    await this.holdBanner('morale')
    this.moraleTests = null
    if (this.active) this.refresh()
  }

  /** The AI picks who activates first (in the tutorial, the script); if it asks for something the rules refuse, it goes first itself */
  private async cpuChooseFirst(player: Player): Promise<GameEvent[]> {
    const events = await this.tutorialCpu()
    if (events) return events
    try {
      const move = cpuMove(this.game, player, { level: this.level })
      if (move) return move()
    } catch (error) {
      if (!(error instanceof RuleError)) throw error
    }
    return this.game.chooseFirst(player)
  }

  /**
   * Keeps the banner on screen with Continue until it is clicked (or Enter) or `BANNER_TIME` passes.
   * Real time, not the game speed: it is there to be read. The menu stops the game, the banner too.
   */
  private async holdBanner(kind: BannerKind) {
    let closed = false
    const close = new Promise<void>(resolve => {
      this.closeBanner = () => {
        closed = true
        resolve()
      }
    })
    // the tutorial explains the banner in its panel: it stays until Continue
    const tutorial = this.activeTutorial()
    tutorial?.openBanner(kind)
    this.refresh()
    await (tutorial ? close : Promise.race([close, new Promise(resolve => window.setTimeout(resolve, BANNER_TIME))]))
    while (!closed && this.menuOpen && this.active) await gameDelay(120)
    this.closeBanner = null
    this.tutorial?.closeBanner(kind)
  }

  private teardown() {
    this.active = false
    if (this.tutorial) {
      this.tutorial.dispose()
      this.tutorial = null
      lockSpeed(null)
      window.clearInterval(this.blinkTimer)
    }
    this.stopLanguage?.()
    this.stopLanguage = null
    window.clearTimeout(this.diceTimer)
    this.dice = null
    MatchMusic.stop()
    window.removeEventListener('keydown', this.onKey)
    window.removeEventListener('resize', this.fitCamera)
    this.subscriptions.forEach(subscription => subscription.close())
    this.subscriptions = []
    this.hud?.remove()
    this.hud = null
    this.views.clear()
    this.clear()
  }

  private setMenu(open: boolean) {
    this.menuOpen = open
    this.optionsOpen = false
    this.quitArmed = false
    this.refresh()
  }

  private setOptions(open: boolean) {
    this.optionsOpen = open
    this.quitArmed = false
    this.refresh()
  }

  private restart() {
    this.teardown()
    this.start()
  }

  /** After the tutorial: a real match on the same map with the same troops, against the AI, in the standard formation */
  private realMatch() {
    this.tutorialMode = false
    this.cpu = [1]
    this.level = 'normal'
    this.troops = ['human', 'undead']
    this.edges = ['west', 'east']
    this.placements = [
      defaultDeployment(this.map.data, TROOPS.human, 'west').map(p => p.pos),
      defaultDeployment(this.map.data, TROOPS.undead, 'east').map(p => p.pos)
    ]
    this.restart()
  }

  private async leave() {
    this.teardown()
    await this.engine.goToScene('menu-shell')
    document.querySelector('start-screen-ui')?.remove()
    const start = document.createElement('start-screen-ui') as HTMLElement & { engine: ex.Engine }
    start.engine = this.engine
    document.body.appendChild(start)
  }

  private makeGrid(): ex.Canvas {
    const corners = hexCorners(this.map.layout)
    return new ex.Canvas({
      width: this.map.size.width, height: this.map.size.height, cache: true,
      draw: ctx => {
        ctx.strokeStyle = 'rgba(0, 0, 0, 0.32)'
        ctx.lineWidth = 2
        for (const hex of this.allHexes()) {
          const { x, y } = this.map.hexPixel(hex)
          ctx.beginPath()
          corners.forEach((c, i) => (i === 0 ? ctx.moveTo(x + c.x, y + c.y) : ctx.lineTo(x + c.x, y + c.y)))
          ctx.closePath()
          ctx.stroke()
        }
      }
    })
  }

  private allHexes(): Axial[] {
    const list: Axial[] = []
    for (let row = 0; row < this.map.data.rows; row++) {
      for (let col = 0; col < this.map.data.cols; col++) list.push({ q: col - (row - (row & 1)) / 2, r: row })
    }
    return list
  }

  // --------------------------------------------------------- who plays

  private isCpu(player: number): boolean {
    return this.cpu.includes(player as Player)
  }

  /** The player the game is waiting for, if the CPU plays it */
  private waitingCpu(): 0 | 1 | null {
    const { state } = this.game
    const player = state.phase === 'initiative' ? state.initiative : state.phase === 'activation' ? state.activePlayer : state.phase === 'melee' ? state.melee.next : null
    return player !== null && this.isCpu(player) ? player : null
  }

  private async drive() {
    if (this.driving) return
    this.driving = true
    try {
      for (let player = this.waitingCpu(); player !== null && this.active; player = this.waitingCpu()) {
        this.refresh()
        await gameDelay(CPU_PAUSE)
        // the menu stops the game, the CPU included
        while (this.menuOpen && this.active) await gameDelay(120)
        if (!this.active) return
        // the tutorial's enemy follows the script (the events come from its action, already applied)
        const scripted = await this.tutorialCpu()
        if (!this.active) return
        const move = scripted ? () => scripted : cpuMove(this.game, player, { level: this.level })
        if (!move) break
        if (!await this.run(move)) {
          // the CPU asked for something the rules refuse: never leave the game waiting forever, take a safe action
          await this.run(this.safeMove(player))
        }
      }
    } finally {
      this.driving = false
      if (this.active) this.refresh()
    }
  }

  /** Something that is always legal for whoever the game waits for: hold, fight the first fight, pick who starts */
  private safeMove(player: 0 | 1): () => GameEvent[] {
    const { game } = this
    const { state } = game
    if (state.phase === 'initiative') return () => game.chooseFirst(player)
    if (state.phase === 'melee') {
      const unit = game.meleeChoices(player)[0]
      return () => game.melee(unit.id, game.meleeTargets(unit.id)[0].id)
    }
    const unit = state.current ? game.unit(state.current.unitId) : game.pendingActivations(player)[0]
    return () => game.hold(unit.id)
  }

  /**
   * A player's action (a person, not the AI): the tutorial lets through only the step's action,
   * with the step's dice; anything else shakes its panel
   */
  private async act(action: TutorialAction): Promise<boolean> {
    const tutorial = this.activeTutorial()
    if (tutorial && !tutorial.allows(action)) {
      this.refuseTutorial()
      return false
    }
    tutorial?.begin()
    return this.run(() => applyAction(this.game, action), () => tutorial?.done())
  }

  /**
   * The scripted enemy's next action, applied, or null when this is no tutorial or the script got
   * out of step (then the AI plays on)
   */
  private async tutorialCpu(): Promise<GameEvent[] | null> {
    const tutorial = this.activeTutorial()
    if (!tutorial) return null
    const action = await tutorial.cpuAction()
    if (!action || !this.active) return null
    try {
      const events = applyAction(this.game, action)
      tutorial.cpuDone()
      return events
    } catch (error) {
      if (!(error instanceof RuleError)) throw error
      tutorial.fail(`the rules refused the enemy's ${action.a}: ${error.code}`)
      return null
    }
  }

  /** The tutorial, while it still follows the match */
  private activeTutorial(): TutorialRun | null {
    return this.tutorial && !this.tutorial.broken ? this.tutorial : null
  }

  /** Waits for the tutorial's text steps (Next works meanwhile, even while the game is locked) */
  private async settleTutorial() {
    const tutorial = this.activeTutorial()
    if (!tutorial?.waitingNext) return
    this.settling = true
    this.refresh()
    try {
      await tutorial.settle()
    } finally {
      this.settling = false
    }
    this.refresh()
  }

  private tutorialNext() {
    const tutorial = this.activeTutorial()
    if (!tutorial?.waitingNext || this.menuOpen || (this.locked && !this.settling)) return
    playSound(Resources.SelectSound)
    tutorial.next()
  }

  private refuseTutorial() {
    playSound(Resources.DeniedSound)
    this.tutorial?.refuse()
  }

  /** Runs one change of the game, animates what happened and keeps the interface in step (`applied`: right after the change went through) */
  private async run(change: () => GameEvent[], applied?: () => void): Promise<boolean> {
    if (this.locked) return false
    let events: GameEvent[]
    try {
      events = change()
      applied?.()
    } catch (error) {
      if (error instanceof RuleError) {
        this.message = t().onagro.error(error.code)
        this.refresh()
        return false
      }
      throw error
    }
    this.locked = true
    this.message = ''
    this.overlay.flagDirty()
    this.addLog(events)
    try {
      await this.animate(events)
    } finally {
      this.locked = false
    }
    if (!this.active) return true
    this.syncSelection()
    this.refresh()
    void this.drive()
    return true
  }

  private addLog(events: GameEvent[]) {
    for (const event of events) this.logLines.push(...describeEvent(this.game, event, this.sideNames()))
    if (this.logLines.length > 200) this.logLines.splice(0, this.logLines.length - 200)
  }

  // ------------------------------------------------------- animations

  private center(hex: Axial): ex.Vector {
    const { x, y } = this.map.hexPixel(hex)
    return ex.vec(x, y)
  }

  private floatText(at: ex.Vector, text: string, color: string) {
    const label = new ex.Actor({ pos: at.add(ex.vec(0, -40)), z: 6 })
    label.graphics.use(new ex.Text({
      text,
      font: new ex.Font({ family: 'notjamslab14', size: 34, color: ex.Color.fromHex(color), shadow: { blur: 0, offset: ex.vec(3, 3), color: ex.Color.Black } })
    }))
    this.add(label)
    void label.actions.moveBy(ex.vec(0, -60), 90).fade(0, 350).die().toPromise()
  }

  private unitCenter(id: number): ex.Vector | null {
    const view = this.views.get(id)
    return view ? view.root.pos.clone() : null
  }

  private async animate(events: GameEvent[]) {
    const moraleShown = new Set<GameEvent>()
    for (const [index, event] of events.entries()) {
      if (!this.active) return
      switch (event.type) {
      case 'move':
      case 'retreat': {
        const view = this.views.get(event.unitId)
        if (!view) break
        const owner = this.game.unit(event.unitId).owner
        // the AI's move: its enemies' zone of control and its path show a moment before it walks, and while it does
        const shown = event.type === 'move' && this.isCpu(owner)
        if (shown) {
          this.cpuMoving = { owner, path: event.path }
          this.overlay.flagDirty()
          await gameDelay(CPU_MOVE_PREVIEW)
        }
        playSound(Resources.MoveSound)
        for (const hex of event.path.slice(1)) {
          const target = this.center(hex)
          const dx = target.x - view.root.pos.x
          if (Math.abs(dx) > 4) view.sprite.graphics.flipHorizontal = dx < 0
          await view.root.actions.moveTo(target, 520).toPromise()
        }
        if (shown) {
          this.cpuMoving = null
          this.overlay.flagDirty()
        }
        break
      }
      case 'shot': {
        const from = this.unitCenter(event.shooterId)
        const to = this.unitCenter(event.hitUnitId ?? event.targetId)
        if (!from || !to) break
        if (event.outOfRange) {
          this.floatText(from, t().onagro.forecast.outOfRange.split(':')[0], '#ff8c42')
          break
        }
        playSound(Resources.BowSound)
        await arrowEffect(this, from, to, event.hit)
        if (!event.hit) this.floatText(to, t().onagro.miss, '#cccccc')
        // the guide's friendly fire: the hit went to an ally engaged with the target
        else if (event.hitUnitId !== null && event.hitUnitId !== event.targetId) this.floatText(to, t().onagro.friendlyFire, '#ff8c42')
        break
      }
      case 'strike': {
        this.showDice(event)
        playSound(Resources.DiceSound)
        await gameDelay(260)
        playSound(event.dealt > 0 ? Resources.HitSound : Resources.MissSound)
        const target = this.unitCenter(event.defenderId)
        if (target) this.floatText(target, event.dealt > 0 ? `-${event.dealt}` : '0', event.dealt > 0 ? '#ff4d4d' : '#9ea3b8')
        const own = event.attackerId !== null ? this.unitCenter(event.attackerId) : null
        if (own && event.backlash > 0) this.floatText(own, `-${event.backlash}`, '#ff8c42')
        if (event.attackerId !== null && event.kind === 'melee' && target) {
          const view = this.views.get(event.attackerId)
          if (view) {
            const dx = target.x - view.root.pos.x
            if (Math.abs(dx) > 4) view.sprite.graphics.flipHorizontal = dx < 0
            const home = view.root.pos.clone()
            await view.root.actions.moveTo(home.add(target.sub(home).scale(0.3)), 700).moveTo(home, 700).toPromise()
          }
        } else {
          await gameDelay(220)
        }
        break
      }
      case 'cast': {
        playSound(event.spell === 'fireball' ? Resources.FireSound : event.spell === 'heal' ? Resources.HealSound : event.spell === 'thorn-rain' ? Resources.ThornsSound : Resources.SkillSound)
        if (typeof event.target === 'number') {
          const at = this.unitCenter(event.target)
          const from = this.unitCenter(event.casterId)
          if (at) {
            this.floatText(at, t().onagro.spells[event.spell].name, SPELLS[event.spell].school === 'necromancy' ? '#9dffb0' : '#4cc9f0')
            if (event.spell === 'magic-shield') await shieldEffect(this, at)
            else if (event.spell === 'fear') await fearEffect(this, at)
            else if (event.spell === 'affliction' && from) await afflictionEffect(this, from, at)
          }
        } else if (SPELLS[event.spell].kind === 'raise') {
          // the unit itself appears with the 'raised' event that follows
          this.flash = [{ hex: event.target, fill: 'rgba(157,255,176,0.4)' }]
          this.overlay.flagDirty()
          await raiseEffect(this, this.center(event.target))
          this.flash = []
          this.overlay.flagDirty()
        } else {
          const color = event.spell === 'fireball' ? 'rgba(255,120,30,0.45)' : 'rgba(80,220,80,0.4)'
          const area = [event.target, ...hexNeighbors(event.target)]
          this.flash = area.map(hex => ({ hex, fill: color }))
          this.overlay.flagDirty()
          const from = this.unitCenter(event.casterId)
          const points = area.map(hex => this.center(hex))
          if (event.spell === 'fireball' && from) await fireballEffect(this, from, this.center(event.target), points)
          else if (event.spell === 'thorn-rain') await thornRainEffect(this, points)
          else await gameDelay(450)
          this.flash = []
          this.overlay.flagDirty()
        }
        break
      }
      case 'heal': {
        const at = this.unitCenter(event.unitId)
        if (at && event.amount > 0) {
          this.floatText(at, `+${event.amount}`, '#4ee06a')
          await healEffect(this, at)
        }
        break
      }
      case 'out': {
        const view = this.views.get(event.unitId)
        playSound(Resources.DeathSound)
        if (this.selected === event.unitId) this.clearSelection()
        if (view) {
          await view.root.actions.fade(0, 450).toPromise()
          view.root.kill()
          this.views.delete(event.unitId)
        }
        break
      }
      case 'save': {
        const at = this.unitCenter(event.unitId)
        const damage = SPELLS[event.spell].damage ?? 0
        if (at) this.floatText(at, event.saved || damage === 0 ? '0' : `-${damage}`, event.saved ? '#9ea3b8' : '#ff4d4d')
        playSound(event.saved ? Resources.MissSound : Resources.HitSound)
        await gameDelay(300)
        break
      }
      case 'raised': {
        // back from the dead: a new sprite where it got up (the raise effect already played)
        const unit = this.game.unit(event.unitId)
        this.views.get(unit.id)?.root.kill()
        const view = new UnitView(unit, () => this.selected, this.faceLeft(unit.owner), this.colorOf(unit.owner).hex, this.map.hexPixel(unit.pos!), unit.owner)
        this.views.set(unit.id, view)
        this.add(view.root)
        playSound(Resources.SkillSound)
        await gameDelay(350)
        break
      }
      case 'turn-end':
        this.endedTurn = event.turn
        break
      case 'turn-start':
        // the recoveries of this turn first, so the turn banner then stays on its own
        await this.showMorale(events.slice(index + 1).filter(next => next.type === 'recovery'), moraleShown)
        await this.announceTurn(event)
        break
      case 'recovery':
      case 'morale-test': {
        // every test of this moment at once (the end of the turn tests many units); retreats play after
        const end = events.findIndex((next, at) => at > index && (next.type === 'turn-end' || next.type === 'turn-start' || next.type === 'game-over'))
        await this.showMorale(events.slice(index, end === -1 ? undefined : end).filter(next => next.type === event.type), moraleShown)
        this.refreshBars()
        break
      }
      case 'first-player':
        this.banner = null
        break
      case 'game-over':
        if (this.tutorialMode) markTutorialDone()
        // the last blow and the last fall play out first; only then the result
        await gameDelay(GAME_OVER_PAUSE)
        this.overShown = true
        MatchMusic.stop()
        // the defeat sound only when the AI beats a player
        playSound(event.winner !== 'draw' && this.cpu.length === 1 && this.cpu.includes(event.winner) ? Resources.DefeatSound : Resources.VictorySound)
        break
      case 'damage':
      case 'last-breath':
      case 'shield':
      case 'shield-ended':
        this.refreshBars()
        break
      default:
        break
      }
    }
    this.refreshBars()
  }

  /** Shows the dice of an attack pair by pair for a few seconds */
  private showDice(event: Extract<GameEvent, { type: 'strike' }>) {
    const text = t().onagro
    const name = (id: number) => this.game.unit(id).sheet.name
    const title = event.attackerId === null || event.kind === 'spell'
      ? name(event.defenderId)
      : `${name(event.attackerId)} → ${name(event.defenderId)}`
    this.dice = {
      title,
      pairs: event.roll.comparison.pairs.map(pair => ({ attack: pair.attack, defense: pair.defense, effect: pair.effect, label: text.dice[pair.effect] })),
      summary: text.dice.total(event.dealt, event.backlash)
    }
    window.clearTimeout(this.diceTimer)
    // the tutorial's texts talk about the dice: they stay until the next attack
    if (!this.tutorial) this.diceTimer = window.setTimeout(() => {
      this.dice = null
      this.refresh()
    }, 4500)
    this.refresh()
  }

  private refreshBars() {
    const { state } = this.game
    for (const view of this.views.values()) view.update(state.phase === 'activation' && view.unit.activated, state.turn)
  }

  // ------------------------------------------------------------ input

  private syncSelection() {
    const { state } = this.game
    if (state.phase === 'activation') {
      if (state.current) {
        this.selected = state.current.unitId
        return
      }
      const unit = this.selectedUnit()
      if (!unit || !inPlay(unit) || unit.activated || unit.owner !== state.activePlayer) this.clearSelection()
    } else if (state.phase === 'melee') {
      const unit = this.selectedUnit()
      if (!unit || !this.game.meleeChoices(state.melee.next).includes(unit)) this.clearSelection()
    } else {
      this.clearSelection()
    }
  }

  /** The units the human player may pick now (Tab cycles through them, the troop list selects them) */
  private selectableUnits(): UnitState[] {
    const { state } = this.game
    if (state.phase === 'activation' && !this.isCpu(state.activePlayer)) return this.game.pendingActivations(state.activePlayer)
    if (state.phase === 'melee' && !this.isCpu(state.melee.next)) return this.game.meleeChoices(state.melee.next)
    return []
  }

  /** A click on a unit in the troop list */
  private pickUnit(id: number) {
    if (this.menuOpen || this.locked) return
    const { state } = this.game
    const unit = this.selectableUnits().find(u => u.id === id)
    if (!unit || (state.current && state.current.unitId !== id)) return
    if (this.tutorialBlocksUnit(unit.id)) return
    playSound(Resources.SelectSound)
    this.select(unit)
    this.refresh()
  }

  /** The pointer over a unit in the troop list lights it up on the map */
  private hoverUnit(id: number | null) {
    const unit = id === null ? null : this.game.state.units.find(u => u.id === id)
    this.hover = unit?.pos ?? null
    this.refresh()
  }

  /** The selected unit, unless it left the game meanwhile (killed by a free attack, surrendered...) */
  private selectedUnit(): UnitState | null {
    if (this.selected === null) return null
    const unit = this.game.unit(this.selected)
    return inPlay(unit) ? unit : null
  }

  private clearSelection() {
    this.selected = null
    this.mode = 'none'
    this.spell = null
  }

  private select(unit: UnitState) {
    this.selected = unit.id
    this.spell = null
    const { state } = this.game
    this.mode = state.phase === 'activation' && !state.current && this.game.reachable(unit.id).range.length > 0 ? 'move' : 'none'
    // the tutorial shows the moves only when the step is a move: the other actions start from their button
    const expected = this.activeTutorial()?.expected()
    if (expected && expected.a !== 'move') this.mode = 'none'
  }

  /**
   * With a finger there is no hover: the first tap on a target shows its forecast, the second
   * tap on the same hex does it. With a mouse the pointer is already there, so this always passes.
   */
  private confirmed(hex: Axial, touch: boolean): boolean {
    if (!touch || (this.hover?.q === hex.q && this.hover?.r === hex.r)) return true
    this.hover = hex
    this.refresh()
    return false
  }

  private async onClick(hex: Axial | null, touch = false) {
    if (!hex || this.locked || this.menuOpen || !this.active || this.game.state.phase === 'ended') return
    const { state } = this.game
    const clicked = this.game.unitAt(hex)
    const selected = this.selectedUnit()

    const at = offsetOf(hex)
    if (state.phase === 'activation') {
      if (this.isCpu(state.activePlayer)) return
      if (selected) {
        if (this.mode === 'move' && this.game.reachable(selected.id).canStopAt(hex)) {
          if (!this.confirmed(hex, touch)) return
          await this.act({ a: 'move', unit: selected.id, to: at })
          return
        }
        if (this.mode === 'shoot' && clicked && clicked.owner !== selected.owner) {
          if (!this.confirmed(hex, touch)) return
          await this.act({ a: 'shoot', unit: selected.id, target: clicked.id })
          return
        }
        if (this.mode === 'cast' && this.spell) {
          const spell = this.spell
          const kind = SPELLS[spell].kind
          if (kind === 'area' || (kind === 'raise' && !clicked)) {
            if (!this.confirmed(hex, touch)) return
            await this.act({ a: 'cast', unit: selected.id, spell, hex: at })
            return
          }
          if ((kind === 'enemy' && clicked && clicked.owner !== selected.owner) || (kind === 'target' && clicked && clicked.owner === selected.owner)) {
            if (!this.confirmed(hex, touch)) return
            await this.act({ a: 'cast', unit: selected.id, spell, target: clicked!.id })
            return
          }
        }
      }
      if (clicked && clicked.owner === state.activePlayer && !clicked.activated && (!state.current || state.current.unitId === clicked.id)) {
        // the tutorial: only the unit of the step
        if (this.tutorialBlocksUnit(clicked.id)) return
        this.select(clicked)
      } else if (!state.current) {
        this.clearSelection()
      }
      this.refresh()
    } else if (state.phase === 'melee') {
      if (this.isCpu(state.melee.next)) return
      if (selected && clicked && this.game.adjacentEnemies(selected.id).includes(clicked)) {
        if (!this.confirmed(hex, touch)) return
        await this.act({ a: 'melee', unit: selected.id, target: clicked.id })
        return
      }
      if (clicked && this.game.meleeChoices(state.melee.next).includes(clicked)) {
        if (this.tutorialBlocksUnit(clicked.id)) return
        this.selected = clicked.id
      } else this.selected = null
      this.refresh()
    }
  }

  /** In the tutorial, picking another unit than the step's is refused (true: refused) */
  private tutorialBlocksUnit(unitId: number): boolean {
    const tutorial = this.activeTutorial()
    if (!tutorial || tutorial.allowsUnit(unitId)) return false
    this.refuseTutorial()
    return true
  }

  /** In the tutorial, only the step's action button can be picked (true: refused) */
  private tutorialBlocksMode(mode: Mode, spell: SpellId | null): boolean {
    const expected = this.activeTutorial()?.expected()
    if (!this.activeTutorial()) return false
    const fits = !!expected && expected.a !== 'first' && expected.unit === this.selected && (
      (expected.a === 'move' && mode === 'move') ||
      (expected.a === 'shoot' && mode === 'shoot') ||
      (expected.a === 'cast' && mode === 'cast' && expected.spell === spell))
    if (!fits) this.refuseTutorial()
    return !fits
  }

  /** Keyboard (the gamepad sends these same keys): M move, S shoot, C cast, H hold, Tab next unit, Esc cancel, L log, G grid */
  private onKey = (event: KeyboardEvent) => {
    if (!this.active || event.ctrlKey || event.metaKey || event.altKey) return
    const key = event.key.toLowerCase()
    if (this.menuOpen) {
      // in the menu only Esc does anything: from the Options back to the menu, from the menu back to the game
      if (key === 'escape') {
        if (this.optionsOpen) this.setOptions(false)
        else this.setMenu(false)
        event.preventDefault()
      }
      return
    }
    const { state } = this.game
    if (this.closeBanner && (key === 'enter' || key === ' ')) {
      this.closeBanner()
      event.preventDefault()
      return
    }
    // the tutorial's Next (also while it talks over a locked game)
    if (this.activeTutorial()?.waitingNext && (key === 'enter' || key === ' ')) {
      this.tutorialNext()
      event.preventDefault()
      return
    }
    if (this.locked) return
    const own =state.phase === 'activation' && !this.isCpu(state.activePlayer)
    const selected = this.selectedUnit()
    if (key === 'escape') {
      // Esc cancels what is being done; with nothing to cancel it opens the menu
      if (selected && !state.current) this.clearSelection()
      else if (this.message) this.message = ''
      else {
        this.setMenu(true)
        event.preventDefault()
        return
      }
    } else if (key === 'l') {
      this.showLog = !this.showLog
    } else if (key === 'g') {
      this.showGrid = !this.showGrid
      this.gridActor.graphics.isVisible = this.showGrid
    } else if (key === 'tab') {
      const list = this.selectableUnits()
      if (list.length === 0) return
      const at = selected ? list.findIndex(u => u.id === selected.id) : -1
      let next = list[(at + (event.shiftKey ? list.length - 1 : 1)) % list.length]
      // the tutorial: Tab goes straight to the unit of the step
      const expected = this.activeTutorial()?.expected()
      if (expected && expected.a !== 'first') next = list.find(u => u.id === expected.unit) ?? next
      if (this.tutorialBlocksUnit(next.id)) return
      if (state.current && state.current.unitId !== next.id) return
      this.select(next)
      if (next.pos) this.hover = next.pos
    } else if (own && selected && selected.owner === state.activePlayer) {
      if (key === 'm' && !state.current) {
        if (!this.tutorialBlocksMode('move', null)) this.mode = 'move'
      } else if (key === 's' && selected.sheet.ranged) {
        if (!this.tutorialBlocksMode('shoot', null)) this.mode = 'shoot'
      } else if (key === 'c') {
        const spell = selected.sheet.spells.find(id => this.game.spellReady(selected.id, id) && !state.current?.spells.includes(id))
        if (spell && !this.tutorialBlocksMode('cast', spell)) {
          this.mode = 'cast'
          this.spell = spell
        }
      } else if (key === 'h' || key === ' ' || key === 'enter') {
        void this.onHold()
        event.preventDefault()
        return
      } else return
    } else return
    event.preventDefault()
    this.refresh()
  }

  private onPick(detail: { kind: string, spell?: string }) {
    if (this.selected === null || this.locked || this.menuOpen) return
    if (this.tutorialBlocksMode(detail.kind as Mode, (detail.spell as SpellId | undefined) ?? null)) return
    this.mode = detail.kind as Mode
    this.spell = (detail.spell as SpellId | undefined) ?? null
    this.message = ''
    this.refresh()
  }

  private async onHold() {
    if (this.selected === null) return
    await this.act({ a: 'hold', unit: this.selected })
  }

  // ----------------------------------------------------------- drawing

  private refresh() {
    if (!this.active || !this.hud) return
    this.overlay.flagDirty()
    this.refreshBars()
    this.hud.view = this.buildView()
  }

  private marks(): Mark[] {
    const { game } = this
    const { state } = game
    const marks: Mark[] = []
    if (state.phase === 'ended') return marks
    // what the tutorial points at, blinking, over everything else
    const pointed: Mark[] = this.tutorialPointers().hexes.map(hex => ({ hex, stroke: this.blink ? GOLD : '#fff7c2', width: 9, halo: true }))
    // while a change plays out the game is already past it (the unit stands on its new hex, the shot
    // was fired): drawing the plan now would paint it again from there. Only the effects show
    if (this.locked) return [...this.cpuMoveMarks(), ...this.flash, ...pointed]
    const selected = this.selectedUnit()
    const human = state.phase === 'activation' ? !this.isCpu(state.activePlayer) : state.phase === 'melee' ? !this.isCpu(state.melee.next) : false

    // who can still act
    if (human && state.phase === 'activation') {
      for (const unit of game.pendingActivations(state.activePlayer)) if (unit !== selected) marks.push({ hex: unit.pos!, stroke: 'rgba(255,210,63,0.75)', width: 3 })
    }
    if (human && state.phase === 'melee') {
      for (const unit of game.meleeChoices(state.melee.next)) marks.push({ hex: unit.pos!, stroke: GOLD, width: 4 })
    }

    if (selected && human) {
      marks.push({ hex: selected.pos!, stroke: GOLD, width: 6 })
      if (state.phase === 'melee') {
        for (const enemy of game.adjacentEnemies(selected.id)) marks.push({ hex: enemy.pos!, fill: 'rgba(255,60,60,0.4)', stroke: '#ff9a9a', width: 4 })
      } else if (this.mode === 'move') {
        const reach = game.reachable(selected.id)
        for (const hex of reach.range) marks.push({ hex, fill: 'rgba(70,140,255,0.38)', stroke: 'rgba(170,210,255,0.9)', width: 3 })
        if (this.hover && reach.canStopAt(this.hover)) {
          for (const hex of reach.pathTo(this.hover).slice(1)) marks.push({ hex, fill: 'rgba(255,240,120,0.5)', stroke: '#fff', width: 3 })
        }
      } else if (this.mode === 'shoot') {
        for (const enemy of game.shootTargets(selected.id)) {
          const inRange = game.forecastShot(selected.id, enemy.id).inRange
          marks.push({ hex: enemy.pos!, fill: inRange ? 'rgba(255,60,60,0.42)' : 'rgba(255,160,40,0.3)', stroke: inRange ? '#ff9a9a' : '#ffb347', width: 4 })
        }
      } else if (this.mode === 'cast' && this.spell) {
        const def = SPELLS[this.spell]
        if (def.kind === 'area') {
          for (const hex of this.allHexes()) {
            if (hexDistance(selected.pos!, hex) <= def.range && (!def.needsSight || lineOfSight(this.map.data, selected.pos!, hex))) {
              marks.push({ hex, fill: 'rgba(255,170,60,0.16)' })
            }
          }
          if (this.hover) for (const hex of [this.hover, ...hexNeighbors(this.hover)]) marks.push({ hex, fill: 'rgba(255,90,30,0.5)', stroke: '#ffb347', width: 3 })
        } else if (def.kind === 'enemy') {
          // enemies in range and sight; the immune to fear only outlined
          for (const enemy of game.state.units) {
            if (!inPlay(enemy) || enemy.owner === selected.owner) continue
            const f = game.forecastCurse(selected.id, this.spell, enemy.id)
            if (!f.inRange || !f.inSight) continue
            marks.push(f.immune
              ? { hex: enemy.pos!, stroke: 'rgba(200,200,200,0.7)', width: 3, dash: true }
              : { hex: enemy.pos!, fill: 'rgba(157,102,214,0.45)', stroke: '#c9a6ff', width: 4 })
          }
        } else if (def.kind === 'raise') {
          for (const hex of this.allHexes()) {
            const terrain = terrainAt(this.map.data, hex)
            if (hexDistance(selected.pos!, hex) > def.range || !terrain || terrain.move === 'blocked' || game.unitAt(hex)) continue
            marks.push({ hex, fill: 'rgba(157,255,176,0.22)', stroke: 'rgba(157,255,176,0.6)', width: 2 })
          }
          if (this.hover && !game.unitAt(this.hover)) marks.push({ hex: this.hover, fill: 'rgba(157,255,176,0.5)', stroke: '#9dffb0', width: 4 })
        } else {
          for (const unit of game.unitsOf(selected.owner)) {
            if (hexDistance(selected.pos!, unit.pos!) <= def.range) marks.push({ hex: unit.pos!, fill: 'rgba(80,220,120,0.4)', stroke: '#8dffb0', width: 4 })
          }
        }
      }
    }
    if (this.hover) marks.push({ hex: this.hover, stroke: 'rgba(255,255,255,0.9)', width: 3 })

    // zone of control of the enemy, while choosing where to move: entering it ends the move
    if (selected && human && state.phase === 'activation' && this.mode === 'move') marks.push(...this.zocMarks(selected.owner))

    // who is fighting whom: a line between every pair of engaged units
    for (const unit of game.unitsOf(0)) {
      for (const enemy of game.adjacentEnemies(unit.id)) marks.push({ hex: unit.pos!, to: enemy.pos!, stroke: 'rgba(255,60,60,0.95)', width: 6 })
    }
    return [...marks, ...this.flash, ...pointed]
  }

  /**
   * What the tutorial points at now: hexes on the map, units in the troop lists and a button of
   * the HUD. First the unit of the step, then (once it is selected and in the right mode) its target.
   */
  private tutorialPointers(): { hexes: Axial[], units: number[], button: string | null } {
    const none = { hexes: [], units: [], button: null }
    const tutorial = this.activeTutorial()
    if (!tutorial || !this.game) return none
    if (this.locked && !this.settling) {
      // a banner of the tutorial: its Continue
      return tutorial.shownStep()?.kind === 'banner' && this.closeBanner ? { ...none, button: 'ok' } : none
    }
    const step = tutorial.step
    if (!step || step.kind === 'cpu' || step.kind === 'banner') return none
    const posOf = (id: number) => this.game.unit(id).pos
    if (step.kind === 'info') {
      const units = step.units ?? []
      const hexes = [...(step.hexes ?? []).map(hexOf), ...units.map(posOf).filter((pos): pos is Axial => !!pos)]
      return { hexes, units, button: null }
    }
    const action = step.action
    if (action.a === 'first') return { ...none, button: `first-${action.player}` }
    const unitPos = posOf(action.unit)
    if (this.selected !== action.unit) return { hexes: unitPos ? [unitPos] : [], units: [action.unit], button: null }
    const target = (id: number) => {
      const pos = posOf(id)
      return { ...none, hexes: pos ? [pos] : [] }
    }
    switch (action.a) {
    case 'move': return this.mode === 'move' ? { ...none, hexes: [hexOf(action.to)] } : { ...none, button: 'move' }
    case 'shoot': return this.mode === 'shoot' ? target(action.target) : { ...none, button: 'shoot' }
    case 'melee': return target(action.target)
    case 'hold': return { ...none, button: 'hold' }
    case 'cast':
      if (this.mode !== 'cast' || this.spell !== action.spell) return { ...none, button: action.spell }
      return action.hex ? { ...none, hexes: [hexOf(action.hex)] } : target(action.target!)
    }
  }

  /** The zone of control of the enemies of `owner`: the hexes next to them, where a move ends */
  private zocMarks(owner: Player): Mark[] {
    const marks: Mark[] = []
    const zone = new Set<string>()
    for (const enemy of this.game.state.units.filter(u => inPlay(u) && u.owner !== owner)) {
      for (const hex of hexNeighbors(enemy.pos!)) {
        if (!inMap(this.map.data, hex) || zone.has(`${hex.q},${hex.r}`) || terrainAt(this.map.data, hex)?.move === 'blocked') continue
        zone.add(`${hex.q},${hex.r}`)
        marks.push({ hex, fill: 'rgba(255,40,40,0.2)', stroke: '#ff5050', width: 4, dash: true, halo: true })
      }
    }
    return marks
  }

  /** The AI moving a unit: the zone of control of its enemies and the path it takes, so whoever watches can follow */
  private cpuMoveMarks(): Mark[] {
    if (!this.cpuMoving) return []
    const { owner, path } = this.cpuMoving
    return [
      ...path.slice(1).map(hex => ({ hex, fill: 'rgba(255,240,120,0.45)', stroke: '#fff', width: 3 })),
      ...this.zocMarks(owner)
    ]
  }

  private drawOverlay(ctx: CanvasRenderingContext2D) {
    const corners = hexCorners(this.map.layout)
    for (const mark of this.marks()) {
      const { x, y } = this.map.hexPixel(mark.hex)
      if (mark.to) {
        const end = this.map.hexPixel(mark.to)
        ctx.setLineDash([])
        ctx.beginPath()
        ctx.moveTo(x, y)
        ctx.lineTo(end.x, end.y)
        ctx.lineWidth = mark.width ?? 4
        ctx.strokeStyle = mark.stroke ?? '#f00'
        ctx.stroke()
        continue
      }
      ctx.setLineDash(mark.dash ? (mark.halo ? [14, 8] : [8, 6]) : [])
      ctx.beginPath()
      corners.forEach((c, i) => (i === 0 ? ctx.moveTo(x + c.x * 0.94, y + c.y * 0.94) : ctx.lineTo(x + c.x * 0.94, y + c.y * 0.94)))
      ctx.closePath()
      if (mark.fill) {
        ctx.fillStyle = mark.fill
        ctx.fill()
      }
      if (mark.stroke) {
        // a dark line under the color, so it reads on bright ground too
        if (mark.halo) {
          ctx.setLineDash([])
          ctx.lineWidth = (mark.width ?? 2) + 4
          ctx.strokeStyle = 'rgba(0,0,0,0.55)'
          ctx.stroke()
          ctx.setLineDash(mark.dash ? [14, 8] : [])
        }
        ctx.lineWidth = mark.width ?? 2
        ctx.strokeStyle = mark.stroke
        ctx.stroke()
      }
    }
  }

  // --------------------------------------------------------------- HUD

  private cardOf(unit: UnitState): UnitCardView {
    const text = t().onagro
    const { game } = this
    const turn = game.state.turn
    const status: string[] = []
    if (game?.isEngaged(unit.id)) status.push(text.unit.engaged)
    const abilities = unit.sheet.abilities.map(abilityText)
    const { stats } = unit.sheet
    const pdDice = stats.pd + (unit.shield?.pdBonus ?? 0)
    const morale = game ? game.moraleOf(unit.id) : stats.m
    const spells = unit.sheet.spells.map(id => {
      const readyOn = unit.spellReadyOn[id] ?? 0
      const state2 = readyOn === Infinity ? text.unit.afterEffect : turn >= readyOn ? text.unit.ready : text.unit.recharge(readyOn)
      return { name: text.spells[id].name, text: text.spells[id].text, state: state2 }
    })
    return {
      name: unit.sheet.name,
      owner: unit.owner,
      classLabel: text.classes[unit.sheet.class],
      commander: unit.commander,
      stats: { mo: stats.mo, a: stats.a, pa: stats.pa, pv: stats.pv },
      hp: unit.hp,
      // "PD 1d6+2" of the Flagelante; "M –" of the mindless undead
      pd: pdText(stats, unit.shield?.pdBonus ?? 0),
      pdUp: pdDice !== stats.pd,
      morale: moraleText(morale),
      moraleUp: morale !== null && morale !== stats.m,
      ranged: unit.sheet.ranged ? text.unit.ranged(unit.sheet.ranged.range, unit.sheet.ranged.ra) : null,
      status,
      markers: this.markerViews(unit),
      abilities,
      spells,
      terrain: unit.pos ? this.terrainLines(unit.pos).join(' · ') : ''
    }
  }

  /** The unit's markers, as on the map, with their names and what each one means (for the troop lists) */
  private markerViews(unit: UnitState): MarkerView[] {
    const { state } = this.game
    const text = t().onagro
    const { left, right } = unitMarkers(unit, state.phase === 'activation' && unit.activated, state.turn)
    return [...left, ...right].map(marker => {
      const help = text.markers.help
      let line: string
      if (marker === 'shield') line = help.shield(unit.shield?.turnsLeft ?? 0)
      else if (marker === 'recharge') {
        line = help.recharge(unit.sheet.spells
          .filter(id => (unit.spellReadyOn[id] ?? 0) > state.turn)
          .map(id => {
            const readyOn = unit.spellReadyOn[id] ?? 0
            return `${text.spells[id].name} (${readyOn === Infinity ? text.unit.afterEffect : text.unit.recharge(readyOn)})`
          })
          .join(', '))
      } else line = help[marker]
      return { icon: markerIcon(marker), label: text.markers.names[marker], help: line }
    })
  }

  private terrainLines(hex: Axial): string[] {
    const terrain = terrainAt(this.map.data, hex)
    if (!terrain) return []
    const text = t().onagro.terrain
    const lines = [text[terrain.id as keyof typeof text] as string, text[terrain.move]]
    if (terrain.cover === 'light') lines.push(text.coverLight)
    if (terrain.cover === 'heavy') lines.push(text.coverHeavy)
    if (terrain.blocksSight) lines.push(text.blocksSight)
    return lines
  }

  private hoverForecast(selected: UnitState | null, target: UnitState | null, hex: Axial | null): string[] {
    const text = t().onagro.forecast
    const { game } = this
    const percent = (p: number) => Math.round(p * 100)
    const avg = (n: number) => n.toFixed(2)
    if (!selected) return []
    if (game.state.phase === 'melee' && target && game.adjacentEnemies(selected.id).includes(target)) {
      const f = game.forecastMelee(selected.id, target.id)
      return [text.melee(`${f.attackDice}d6 × ${f.defenseDice}d6${f.defenseBonus ? `+${f.defenseBonus}` : ''}`, avg(f.strike.expectedDefenderDamage), percent(f.killChance), percent(f.backlashKillChance))]
    }
    if (this.mode === 'shoot' && target && target.owner !== selected.owner && selected.sheet.ranged) {
      const f = game.forecastShot(selected.id, target.id)
      const lines = f.inRange ? [text.shot(f.needed, percent(f.hitChance), avg(f.expectedDamage), percent(f.killChance))] : [text.outOfRange]
      if (f.enemyChance < 1) lines.push(text.friendlyFire(percent(f.enemyChance)))
      return lines
    }
    if (this.mode === 'cast' && this.spell && SPELLS[this.spell].kind === 'area' && hex) {
      return game.forecastSpell(this.spell, hex).map(item => text.spell(item.unit.sheet.name, avg(item.strike.expectedDefenderDamage), percent(item.killChance)))
    }
    if (this.mode === 'cast' && this.spell && SPELLS[this.spell].kind === 'enemy' && target && target.owner !== selected.owner) {
      const f = game.forecastCurse(selected.id, this.spell, target.id)
      if (f.immune) return [text.immune]
      if (!f.inRange || !f.inSight) return []
      return [this.spell === 'fear' ? text.fear(percent(f.chance)) : text.affliction(percent(f.chance), percent(f.killChance))]
    }
    if (this.mode === 'cast' && this.spell && SPELLS[this.spell].kind === 'raise' && hex && !target) {
      const fallen = game.raisable(selected.owner)[0]
      return fallen ? [text.raise(fallen.sheet.name)] : []
    }
    return []
  }

  private castHint(): string {
    const hints = t().onagro.hints
    const kind = this.spell ? SPELLS[this.spell].kind : null
    return kind === 'enemy' ? hints.castEnemy : kind === 'raise' ? hints.raise : hints.cast
  }

  /** One troop list: every unit of the side, the selected and the hovered one opened in place */
  private rosterView(units: UnitState[], owner: Player, active: boolean, score: number, selected: number | null, hovered: number | null): RosterView {
    const { phase } = this.game.state
    return {
      name: this.sideNames()[owner],
      team: this.colorOf(owner).team,
      score,
      active,
      units: units.filter(u => u.owner === owner).map(unit => {
        const out = !inPlay(unit)
        const open = !out && (unit.id === selected || unit.id === hovered)
        return {
          id: unit.id,
          name: unit.sheet.name,
          portrait: unitPortrait(unit.sheet.id, owner === 1, owner),
          hp: out ? 0 : unit.hp,
          maxHp: unit.sheet.stats.pv,
          commander: unit.commander,
          done: phase === 'activation' && unit.activated,
          markers: out ? [] : this.markerViews(unit),
          out,
          selected: unit.id === selected,
          hovered: unit.id === hovered && unit.id !== selected,
          detail: open ? this.cardOf(unit) : null
        }
      })
    }
  }

  private buildView(): HudView {
    const { game } = this
    const { state } = game
    const text = t().onagro
    const sides = this.sideNames()
    const human = state.phase === 'activation' ? !this.isCpu(state.activePlayer) : state.phase === 'melee' ? !this.isCpu(state.melee.next) : state.phase === 'initiative' ? !this.isCpu(state.initiative) : false
    const busy = !human && state.phase !== 'ended'
    const selected = this.selectedUnit()
    const hovered = this.hover ? game.unitAt(this.hover) : null

    const acting = state.phase === 'activation' ? state.activePlayer : state.phase === 'melee' ? state.melee.next : state.phase === 'initiative' ? state.initiative : null
    const scores = game.scores()
    const rosters = ([0, 1] as const).map(owner =>
      this.rosterView(state.units, owner, acting === owner, scores[owner], selected?.id ?? null, hovered?.id ?? null)) as [RosterView, RosterView]

    let sideText = ''
    if (state.phase === 'initiative') sideText = text.initiativeFor(sides[state.initiative])
    else if (state.phase === 'activation') sideText = text.activating(sides[state.activePlayer])
    else if (state.phase === 'melee') sideText = text.meleeFor(sides[state.melee.next])

    let hint = ''
    if (human && state.phase === 'activation') {
      hint = !selected ? text.hints.pick : this.mode === 'move' ? text.hints.move : this.mode === 'shoot' ? text.hints.shoot : this.mode === 'cast' ? this.castHint() : text.hints.pick
    } else if (human && state.phase === 'melee') {
      hint = selected ? text.hints.meleeTarget : text.hints.melee
    }

    let actions: ActionBarView | null = null
    if (human && state.phase === 'activation' && selected && selected.owner === state.activePlayer) {
      const current = state.current
      const engaged = game.isEngaged(selected.id)
      actions = {
        move: !current && game.reachable(selected.id).range.length > 0,
        shoot: !!selected.sheet.ranged && !engaged && (!current || current.kind === 'shoot') && game.shootTargets(selected.id).length > 0,
        spells: selected.sheet.spells.map(id => ({
          id,
          label: text.spells[id].name,
          enabled: !engaged && (!current || current.kind === 'cast') && !(current?.spells.includes(id)) && game.spellReady(selected.id, id)
        })),
        hold: true,
        holdLabel: current ? text.actions.finish : text.actions.hold,
        mode: this.mode,
        spell: this.spell
      }
    }

    const over = this.overView(rosters)

    return {
      turnText: text.turn(state.turn, state.maxTurns),
      phaseText: text.phase[state.phase],
      sideText,
      rosters,
      banner: this.bannerView(rosters),
      morale: this.moraleView(rosters),
      hint,
      message: this.message,
      hoverLines: this.hoverForecast(selected, hovered, this.hover),
      terrainLines: this.hover && !hovered ? this.terrainLines(this.hover) : [],
      actions,
      log: this.logLines,
      showLog: this.showLog,
      dice: this.dice,
      menuButton: text.menuScreen.title,
      menu: this.menuView(),
      busy,
      over,
      tutorial: this.tutorialView()
    }
  }

  /** The part of the HUD the tutorial's text step talks about */
  private tutorialPart(): 'rosters' | 'turn' | 'dice' | null {
    const step = this.activeTutorial()?.step
    if (step?.kind !== 'info' || (this.locked && !this.settling)) return null
    return step.ui === 'rosters' || step.ui === 'turn' || step.ui === 'dice' ? step.ui : null
  }

  /** The tutorial's panel: the step's text (kept while the game plays something out), Next, and what to click */
  private tutorialView(): TutorialView | null {
    const tutorial = this.tutorial
    if (!tutorial) return null
    const text = t().tutorial
    const idle = !this.locked || this.settling
    let body: string
    if (tutorial.broken) body = text.ui.broken
    else {
      const step = tutorial.shownStep()
      if (step?.kind === 'banner') this.tutorialText = step.text
      else if (idle && step) this.tutorialText = step.kind === 'cpu' ? 'watch' : step.text
      else if (!this.tutorialText && step && step.kind !== 'cpu') this.tutorialText = step.text
      const key = this.tutorialText
      body = key === 'watch' || key === null ? text.ui.watch : text.steps[key]
    }
    const pointers = this.tutorialPointers()
    return {
      title: text.ui.title,
      text: body,
      canNext: !tutorial.broken && tutorial.waitingNext && idle && !this.menuOpen,
      next: text.ui.next,
      skip: this.skipArmed ? text.ui.skipSure : text.ui.skip,
      skipArmed: this.skipArmed,
      progress: tutorial.progress,
      shake: tutorial.refusals,
      highlight: { button: pointers.button, units: pointers.units, part: this.tutorialPart() }
    }
  }

  /** The end of the match, explained: why it ended and where each side's points came from */
  private overView(rosters: [RosterView, RosterView]): GameOverView | null {
    const { state } = this.game
    if (state.phase !== 'ended' || state.winner === null || !this.overShown) return null
    const text = t().onagro.over
    const sides = this.sideNames()
    const winner = state.winner
    const scores = this.game.scores()
    const standing = ([0, 1] as const).map(side => state.units.filter(u => u.owner === side && inPlay(u)).length)
    const reason = standing[0] === 0 && standing[1] === 0 ? text.bothWiped
      : standing[0] === 0 ? text.wiped(sides[0])
        : standing[1] === 0 ? text.wiped(sides[1])
          : winner === 'draw' ? text.turnsDraw(state.maxTurns) : text.turnsWin(state.maxTurns)
    const tutorial = this.tutorialMode ? t().tutorial.ui : null
    return {
      title: tutorial ? tutorial.complete : winner === 'draw' ? text.draw : text.win(sides[winner]),
      again: tutorial ? tutorial.playMatch : text.again,
      reason: tutorial ? tutorial.completeText : reason,
      sides: ([0, 1] as const).map(side => {
        const own = state.units.filter(u => u.owner === side)
        const enemies = state.units.filter(u => u.owner !== side)
        const commander = enemies.find(u => u.commander)
        const lines = [text.defeated(enemies.filter(u => u.out !== null).length)]
        if (commander) lines.push(commander.out !== null ? text.commanderOut : text.commanderIn)
        lines.push(text.left(standing[side], own.length))
        return { name: sides[side], team: rosters[side].team, points: scores[side], won: winner === side, lines }
      }),
      rule: text.rule
    }
  }

  private moraleView(rosters: [RosterView, RosterView]): MoraleBannerView | null {
    if (!this.moraleTests) return null
    const text = t().onagro.moraleBanner
    return {
      title: text.title,
      rule: text.rule,
      rows: this.moraleTests.map(event => {
        const unit = this.game.unit(event.unitId)
        const passed = event.type === 'recovery' ? event.recovered : event.passed
        return {
          name: unit.sheet.name,
          team: rosters[unit.owner].team,
          tag: event.type === 'recovery' ? text.recovery : event.cause === 'fear' ? text.fear : null,
          roll: text.roll(event.roll, event.morale),
          result: passed ? (event.type === 'recovery' ? text.recovered : text.passed) : text.failed(event.failures),
          passed
        }
      }),
      ok: t().onagro.banner.ok
    }
  }

  private bannerView(rosters: [RosterView, RosterView]): TurnBannerView | null {
    if (!this.banner) return null
    const { ended, start, first } = this.banner
    const text = t().onagro
    const sides = this.sideNames()
    const holder = start.initiative
    const choosing = this.game.state.phase === 'initiative' && !this.isCpu(holder)
    return {
      ended: ended === null ? null : text.banner.turnOver(ended),
      title: text.banner.turnBegins(start.turn, this.game.state.maxTurns),
      rollsTitle: text.banner.rolls,
      rolls: ([0, 1] as const).map(side => ({ name: sides[side], roll: start.rolls[side], team: rosters[side].team, won: side === holder })),
      result: start.rolls[0] === start.rolls[1] ? text.banner.tie(sides[holder]) : text.initiativeFor(sides[holder]),
      choose: choosing
        ? { question: text.firstQuestion, options: [{ player: 0, label: text.goesFirst(sides[0]) }, { player: 1, label: text.goesFirst(sides[1]) }] }
        : null,
      // the AI's choice, on the same banner as the roll
      chosen: first !== null && this.isCpu(holder) ? text.banner.chose(sides[holder], sides[first]) : null,
      ok: this.closeBanner ? text.banner.ok : null
    }
  }

  private menuView(): HudView['menu'] {
    const text = t().onagro
    return this.menuOpen
      ? {
        title: text.menuScreen.title,
        resume: text.menuScreen.resume,
        options: this.optionsOpen,
        optionsLabel: text.menuScreen.options,
        backLabel: text.menuScreen.back,
        logLabel: text.menuScreen.log(this.showLog),
        gridLabel: text.menuScreen.grid(this.showGrid),
        quit: text.menuScreen.quit,
        confirmQuit: this.quitArmed,
        controlsTitle: text.menuScreen.controlsTitle,
        controls: text.menuScreen.controls
      }
      : null
  }
}
