/**
 * Dice for the ONAGRO rules. Everything that rolls takes a `Dice`, so the
 * game can be played with a seeded generator (simulation), with real random
 * numbers, or with rolls scripted in advance (tests, online sync).
 */

export interface Dice {
  /** One six-sided die: an integer from 1 to 6 */
  d6(): number
}

/** Real random dice */
export const randomDice: Dice = { d6: () => Math.floor(Math.random() * 6) + 1 }

/** Deterministic dice from a seed (mulberry32): the same seed gives the same game */
export function seededDice(seed: number): Dice {
  let state = seed >>> 0
  return {
    d6() {
      state = (state + 0x6d2b79f5) >>> 0
      let t = state
      t = Math.imul(t ^ (t >>> 15), t | 1)
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
      const unit = ((t ^ (t >>> 14)) >>> 0) / 4294967296
      return Math.floor(unit * 6) + 1
    }
  }
}

/** Dice that hand out the given values in order, and fail when they run out */
export function scriptedDice(values: number[]): Dice & { readonly left: number } {
  const queue = [...values]
  for (const value of queue) {
    if (!Number.isInteger(value) || value < 1 || value > 6) throw new Error(`Not a d6 result: ${value}`)
  }
  return {
    d6() {
      const next = queue.shift()
      if (next === undefined) throw new Error('Scripted dice ran out')
      return next
    },
    get left() {
      return queue.length
    }
  }
}

/** Rolls `count` dice, in order */
export function rollPool(dice: Dice, count: number): number[] {
  return Array.from({ length: Math.max(0, count) }, () => dice.d6())
}

/** 2d6 total (Moral, saving throws) */
export function roll2d6(dice: Dice): number {
  return dice.d6() + dice.d6()
}

/** Dice sorted from the highest to the lowest (how pools are compared) */
export const sortedDesc = (values: number[]): number[] => [...values].sort((a, b) => b - a)
