import type { Axial } from '../hex'

/** The two sides: 0 plays first on turn one's deployment side, 1 the other */
export type Player = 0 | 1

export const otherPlayer = (player: Player): Player => (player === 0 ? 1 : 0)

/** The four classes of the guide */
export type UnitClass = 'hero' | 'veteran' | 'infantry' | 'special'

/** MO, A, PA, PD, M, PV of the sheet. PA and PD are numbers of d6; RA lives on the ranged weapon. */
export interface Stats {
  /** Movimentação: most hexes it can move */
  mo: number
  /** Ataques: attacks (or spells) per activation / melee phase */
  a: number
  /** Poder de Ataque (melee): d6 rolled */
  pa: number
  /** Poder de Defesa: d6 rolled */
  pd: number
  /** Added to the highest defense die ("PD 1d6+2" = pd 1, pdPlus 2) */
  pdPlus?: number
  /** Moral: 2d6 test succeeds on this or less; null = never tests Moral (mindless undead, "M –") */
  m: number | null
  /** Pontos Vitais */
  pv: number
}

export interface RangedWeapon {
  name: string
  /** Range in hexes */
  range: number
  /** Minimum d6 result to hit (4 = 4+) */
  ra: number
  /** d6 of attack power */
  pa: number
}

export type SpellId = 'fireball' | 'magic-shield' | 'thorn-rain' | 'heal' | 'raise-dead' | 'fear' | 'affliction'

/**
 * Abilities printed on the sheets.
 * - inspiration: allies within `radius` get +1 in Moral tests
 * - war-song: allies within `radius` get +2 in Moral and +1d6 of PA
 * - block: when attacked, the attacker rolls its highest PA die again
 * - last-breath: when losing the last PV, 5-6 on 1d6 keeps 1 PV (once)
 * - fury: may reroll one PA die per attack
 * - hate: +1d6 of PA against units of the race `against`
 * - causes-fear (Causa medo): enemies next to it at the end of the turn test Moral
 * - fearless (Imune a medo e sugestão): fear (Causa medo, the Medo spell) never touches it
 * - fanatic (Fanatismo): ignores fear, and does not test Moral for the troop's losses
 * - frenzy (Frenesi): one more attack in melee while wounded
 * - mindless (Moral "–", undead without intelligence): never tests Moral, never fails it
 */
export type AbilityId = 'inspiration' | 'war-song' | 'block' | 'last-breath' | 'fury' | 'hate'
  | 'causes-fear' | 'fearless' | 'fanatic' | 'frenzy' | 'mindless'

export interface Ability {
  id: AbilityId
  radius?: number
  against?: string
}

/** A unit as printed on a sheet (what an army is made of) */
export interface UnitSheet {
  /** Stable id, e.g. 'human-infantry' */
  id: string
  name: string
  faction: string
  race: string
  class: UnitClass
  points: number
  stats: Stats
  ranged?: RangedWeapon
  /** Bonus subtracted from the RA needed to hit with the ranged weapon */
  hitBonus?: number
  spells: SpellId[]
  abilities: Ability[]
}

/** Why a unit left the game */
export type OutReason = 'killed' | 'surrendered' | 'fled'

/** An effect with a duration on a unit (Escudo Mágico) */
export interface ShieldEffect {
  /** Extra d6 of PD */
  pdBonus: number
  /** Turns left; goes down at the end of every turn */
  turnsLeft: number
  casterId: number
}

export interface UnitState {
  id: number
  owner: Player
  sheet: UnitSheet
  /** The troop's commander: worth 2 points, and its fall makes the troop test Moral */
  commander: boolean
  /** Where it stands; null once it left the game */
  pos: Axial | null
  hp: number
  /** Already activated this turn */
  activated: boolean
  /** Moral failure markers (0-3): 1 shaken, 2 retreating, 3 surrendering */
  moraleFailures: number
  /** First turn on which each spell can be cast again (missing = ready) */
  spellReadyOn: Partial<Record<SpellId, number>>
  shield: ShieldEffect | null
  lastBreathUsed: boolean
  out: OutReason | null
}

/** A unit and the hex it starts on; `commander` marks the troop's leader (by default, a Hero) */
export interface Placement {
  sheet: UnitSheet
  pos: Axial
  commander?: boolean
}

export function createUnit(id: number, owner: Player, sheet: UnitSheet, pos: Axial, commander = sheet.class === 'hero'): UnitState {
  return {
    id,
    owner,
    sheet,
    commander,
    pos: { q: pos.q, r: pos.r },
    hp: sheet.stats.pv,
    activated: false,
    moraleFailures: 0,
    spellReadyOn: {},
    shield: null,
    lastBreathUsed: false,
    out: null
  }
}

/** In play: on the map and not eliminated */
export const inPlay = (unit: UnitState): boolean => unit.out === null && unit.pos !== null

/** The commander is worth 2 points; every other unit 1 */
export const pointsOf = (unit: UnitState): number => (unit.commander ? 2 : 1)

export const abilityOf = (sheet: UnitSheet, id: AbilityId): Ability | undefined => sheet.abilities.find(a => a.id === id)

/** Fear (Causa medo, the Medo spell) does not touch it: it causes fear itself, is immune or fanatic, or has no Moral */
export const immuneToFear = (sheet: UnitSheet): boolean =>
  sheet.stats.m === null || sheet.abilities.some(a => a.id === 'causes-fear' || a.id === 'fearless' || a.id === 'fanatic')
