import { LitElement, css, html, nothing } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { theme } from '../ui-components/theme'
import { t } from '../i18n'
import '../ui-components/settings-controls'

/** One of the guide's markers on a unit: the token as on the map, its name and what it means */
export interface MarkerView {
  icon: string
  label: string
  help: string
}

/** What the HUD shows about one unit (the scene builds it from the game; the HUD only draws it) */
export interface UnitCardView {
  name: string
  owner: 0 | 1
  classLabel: string
  commander: boolean
  stats: { mo: number, a: number, pa: number, pv: number }
  hp: number
  /** PD and Moral as they are right now ("1d6+2", "–" for no Moral); `pdUp`/`moraleUp`: raised by a shield or an aura */
  pd: string
  pdUp: boolean
  morale: string
  moraleUp: boolean
  ranged: string | null
  status: string[]
  /** The markers with what each one means */
  markers: MarkerView[]
  abilities: string[]
  spells: { name: string, text: string, state: string }[]
  terrain: string
}

/** One line of a troop list: the unit at a glance; `detail` when it is selected or under the mouse */
export interface RosterUnitView {
  id: number
  name: string
  portrait: string
  hp: number
  maxHp: number
  commander: boolean
  /** Already activated this turn */
  done: boolean
  /** Out of the game (eliminated, surrendered, fled) */
  out: boolean
  /** The unit's markers, as on the map */
  markers: MarkerView[]
  selected: boolean
  hovered: boolean
  detail: UnitCardView | null
}

/** One side of the screen: a troop, its score and its units */
export interface RosterView {
  name: string
  /** Color of the troop (CSS class team-<team>) */
  team: 'blue' | 'red'
  score: number
  /** It is this side's turn to act */
  active: boolean
  units: RosterUnitView[]
}

export interface ActionBarView {
  move: boolean
  shoot: boolean
  spells: { id: string, label: string, enabled: boolean }[]
  hold: boolean
  holdLabel: string
  mode: 'none' | 'move' | 'shoot' | 'cast'
  spell: string | null
}

/** The dice of the last attack, pair by pair (attack against defense, highest first) */
export interface DiceView {
  title: string
  pairs: { attack: number, defense: number | null, effect: 'blocked' | 'hit' | 'excess' | 'ignored' | 'backlash', label: string }[]
  summary: string
}

export interface MenuView {
  title: string
  resume: string
  /** The Options page is open (sound, fullscreen, language, combat log, grid) instead of the menu itself */
  options: boolean
  optionsLabel: string
  backLabel: string
  logLabel: string
  gridLabel: string
  quit: string
  /** The second click on quit leaves the match */
  confirmQuit: boolean
  controlsTitle: string
  controls: string[]
}

/** The message in the middle of the screen between turns: the end of the turn and the initiative roll */
export interface TurnBannerView {
  /** "End of turn n", absent on the first turn */
  ended: string | null
  title: string
  rollsTitle: string
  rolls: { name: string, roll: number, team: 'blue' | 'red', won: boolean }[]
  result: string
  /** The initiative holder is a person: they choose here who activates first */
  choose: { question: string, options: { player: 0 | 1, label: string }[] } | null
  /** The AI holds the initiative: what it is choosing, then who it chose */
  chosen: string | null
  /** After the AI chose: the message closes by itself, or with this button */
  ok: string | null
}

/** The Morale tests that just happened, one line per unit, in the middle of the screen */
export interface MoraleBannerView {
  title: string
  rule: string
  rows: { name: string, team: 'blue' | 'red', tag: string | null, roll: string, result: string, passed: boolean }[]
  ok: string
}

/** The tutorial's panel, in its own band between the map and the action band */
export interface TutorialView {
  title: string
  /** The lesson; `[text]` is highlighted */
  text: string
  /** A text step: Next goes on */
  canNext: boolean
  next: string
  skip: string
  /** The second click on skip leaves the tutorial */
  skipArmed: boolean
  /** 0..1 */
  progress: number
  /** Bumped when the player tries something else: the panel shakes */
  shake: number
  /** What to click: an action button ('move', 'shoot', 'hold', a spell id), a banner button ('first-0', 'first-1', 'ok'), and units of the troop lists */
  highlight: { button: string | null, units: number[], part: 'rosters' | 'turn' | 'dice' | null }
}

/** The end of the match: who won, why, and the points of each side */
export interface GameOverView {
  title: string
  /** The label of the first button (play again, or a real match after the tutorial) */
  again: string
  /** Why it ended: a troop wiped out, or the last turn over */
  reason: string
  sides: { name: string, team: 'blue' | 'red', points: number, won: boolean, lines: string[] }[]
  /** How the points are counted */
  rule: string
}

export interface HudView {
  turnText: string
  phaseText: string
  sideText: string
  /** Player 1 on the left, player 2 on the right */
  rosters: [RosterView, RosterView]
  /** Between turns: the end of the turn and the initiative roll, in the middle of the screen */
  banner: TurnBannerView | null
  /** Morale tests, in the middle of the screen (over the turn banner when both show) */
  morale: MoraleBannerView | null
  hint: string
  message: string
  /** Forecast of what the pointer would do (shot, melee, spell area) */
  hoverLines: string[]
  /** The hex under the pointer, when there is no unit on it */
  terrainLines: string[]
  actions: ActionBarView | null
  log: string[]
  showLog: boolean
  dice: DiceView | null
  /** The match menu, when open (the only settings left in the match; the rest is chosen before it starts) */
  menu: MenuView | null
  menuButton: string
  busy: boolean
  over: GameOverView | null
  /** Only in the tutorial */
  tutorial: TutorialView | null
}

/** Width of each troop rail (left and right), in world pixels at 1920x1080 */
export const HUD_RAIL = 256
/** Height of the status band above the map and of the action band below it, in world pixels */
export const HUD_BAND = 56

/** Height of the tutorial's band, between the map and the action band (only in the tutorial) */
export const HUD_TUTORIAL = 150

/** CSS pixels per world pixel of the HUD (it scales with the window like the canvas) */
export const hudScale = () => Math.min(window.innerWidth / 1920, window.innerHeight / 1080)

const send = (host: HTMLElement, name: string, detail?: unknown) =>
  host.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true }))

/**
 * The match HUD. The map sits centered and never moves; around it, and never over it:
 * a rail per troop on each side (units, score, the selected and hovered unit opened in place),
 * a thin status band above the map and a thin action band below it.
 */
@customElement('onagro-hud')
export class OnagroHud extends LitElement {
  @property({ attribute: false }) view: HudView | null = null

  static styles = [theme, css`
    :host {
      position: fixed;
      inset: 0;
      pointer-events: none;
      --ui-scale: 1;
      /* readable from the couch: every font size below is multiplied by this */
      --text-scale: 1.3;
      --rail: calc(${HUD_RAIL} * var(--u));
      --band: calc(${HUD_BAND} * var(--u));
      --tut: calc(${HUD_TUTORIAL} * var(--u));
      --bg: #0b0e15;
      --surface: rgba(255, 255, 255, 0.035);
      --surface-hi: rgba(255, 255, 255, 0.075);
      --line: rgba(255, 255, 255, 0.09);
      --team-soft: rgba(255, 255, 255, 0.06);
      font-size: calc(15 * var(--t));
      line-height: 1.25;
    }
    .team-blue { --team: #4f8bff; --team-soft: rgba(79, 139, 255, 0.16); }
    .team-red { --team: #ff5a5a; --team-soft: rgba(255, 90, 90, 0.16); }
    .interactive { pointer-events: auto; }

    /* ------------------------------------------------------------ rails */
    .rail {
      position: absolute; top: 0; bottom: 0; width: var(--rail); box-sizing: border-box;
      display: flex; flex-direction: column; gap: calc(6 * var(--u));
      padding: calc(14 * var(--u)) calc(12 * var(--u));
      background: linear-gradient(180deg, var(--team-soft), transparent calc(220 * var(--u))), var(--bg);
      overflow-y: auto; overflow-x: hidden; scrollbar-width: none;
    }
    .rail::-webkit-scrollbar { display: none; }
    .rail.left { left: 0; border-right: calc(1 * var(--u)) solid var(--line); }
    .rail.right { right: 0; border-left: calc(1 * var(--u)) solid var(--line); }
    .head {
      display: flex; align-items: center; justify-content: space-between; gap: calc(8 * var(--u));
      min-height: calc(44 * var(--u)); padding: 0 calc(4 * var(--u)) calc(10 * var(--u)); margin-bottom: calc(6 * var(--u));
      border-bottom: calc(2 * var(--u)) solid var(--line);
    }
    .head.active { border-bottom-color: var(--team); }
    .head .name { color: var(--team); font-size: calc(15 * var(--t)); line-height: 1.15; }
    .head .turn { display: block; margin-top: calc(4 * var(--u)); font-size: calc(11 * var(--t)); color: var(--ink); letter-spacing: 0.08em; text-transform: uppercase; }
    .head .turn::before {
      content: ''; display: inline-block; width: calc(7 * var(--u)); height: calc(7 * var(--u)); margin-right: calc(6 * var(--u));
      background: var(--team); vertical-align: middle; animation: pulse 1.2s steps(2) infinite;
    }
    .head .score { font-size: calc(34 * var(--t)); line-height: 1; color: var(--ink); }
    @keyframes pulse { 50% { opacity: 0.2; } }

    .tile {
      display: grid; grid-template-columns: calc(40 * var(--u)) 1fr auto; align-items: center; gap: calc(4 * var(--u)) calc(10 * var(--u));
      padding: calc(6 * var(--u)) calc(8 * var(--u));
      background: var(--surface); border: calc(2 * var(--u)) solid transparent;
      cursor: pointer; transition: background 120ms, border-color 120ms;
    }
    .tile:hover { background: var(--surface-hi); }
    .tile.hovered { border-color: rgba(255, 255, 255, 0.3); }
    .tile.selected { border-color: var(--team); background: var(--team-soft); }
    .tile.done:not(.selected) .face, .tile.done:not(.selected) .who { opacity: 0.45; }
    .tile.out { cursor: default; opacity: 0.35; filter: grayscale(1); }
    .tile.out .who b { text-decoration: line-through; }
    .face {
      width: calc(40 * var(--u)); height: calc(40 * var(--u)); background: rgba(0, 0, 0, 0.35);
      border-bottom: calc(2 * var(--u)) solid var(--team); overflow: hidden;
    }
    .face img { width: 100%; height: 100%; image-rendering: pixelated; transform: scale(1.35) translateY(8%); }
    .who { min-width: 0; display: flex; flex-direction: column; gap: calc(5 * var(--u)); }
    .who b { font-weight: normal; font-size: calc(14 * var(--t)); line-height: 1.1; overflow-wrap: anywhere; }
    .pips { display: flex; gap: calc(3 * var(--u)); }
    .pips i { width: calc(9 * var(--u)); height: calc(7 * var(--u)); background: #262b38; }
    .pips i.on { background: var(--hp); }
    .pips.low i.on { background: var(--hp-low); }
    .marks { display: flex; flex-wrap: wrap; gap: calc(3 * var(--u)) calc(8 * var(--u)); }
    .mark { display: inline-flex; align-items: center; gap: calc(4 * var(--u)); font-size: calc(11 * var(--t)); color: var(--ink); white-space: nowrap; }
    .mark img, .mark-help img { image-rendering: pixelated; flex: none; }
    .mark img { width: calc(18 * var(--u)); height: calc(18 * var(--u)); }
    .mark-help { display: flex; align-items: flex-start; gap: calc(8 * var(--u)); font-size: calc(12 * var(--t)); line-height: 1.3; color: var(--muted); }
    .mark-help img { width: calc(22 * var(--u)); height: calc(22 * var(--u)); }
    .mark-help b { font-weight: normal; color: var(--ink); }
    .tag {
      font-size: calc(10 * var(--t)); letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted);
      padding: calc(2 * var(--u)) calc(5 * var(--u)); border: calc(1 * var(--u)) solid var(--line); white-space: nowrap;
    }
    .tag.gold { color: var(--gold); border-color: rgba(255, 210, 63, 0.4); }
    .tag.warn { color: var(--orange); border-color: rgba(255, 140, 66, 0.45); }

    /* the unit opened in place: its full sheet */
    .detail { grid-column: 1 / -1; display: flex; flex-direction: column; gap: calc(7 * var(--u)); padding-top: calc(6 * var(--u)); cursor: default; }
    .meta { font-size: calc(12 * var(--t)); color: var(--muted); }
    .stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: calc(2 * var(--u)); text-align: center; }
    .stats div { background: rgba(0, 0, 0, 0.35); padding: calc(4 * var(--u)) 0 calc(3 * var(--u)); }
    .stats small { display: block; color: var(--muted); font-size: calc(10 * var(--t)); }
    .stats b { display: block; font-weight: normal; font-size: calc(17 * var(--t)); }
    .stats b.up { color: var(--hp); }
    .tags { display: flex; flex-wrap: wrap; gap: calc(4 * var(--u)); }
    .note { font-size: calc(12 * var(--t)); line-height: 1.3; }
    .spell { font-size: calc(12 * var(--t)); line-height: 1.3; padding-top: calc(6 * var(--u)); border-top: calc(1 * var(--u)) solid var(--line); }
    .spell b { font-weight: normal; color: var(--mp); }
    .spell span { color: var(--muted); }

    /* ------------------------------------------------------------ bands */
    .band {
      position: absolute; left: var(--rail); right: var(--rail); height: var(--band); box-sizing: border-box;
      display: flex; align-items: center; gap: calc(16 * var(--u)); padding: 0 calc(14 * var(--u));
    }
    .band.top { top: 0; }
    .band.bottom { bottom: 0; }
    .phase { display: flex; flex-direction: column; white-space: nowrap; }
    .phase strong { font-weight: normal; color: var(--gold); font-size: calc(17 * var(--t)); }
    .phase strong span { color: var(--ink); }
    .phase small { color: var(--muted); font-size: calc(12 * var(--t)); }
    .info { flex: 1; min-width: 0; display: flex; align-items: center; justify-content: center; gap: calc(10 * var(--u)); font-size: calc(13 * var(--t)); color: var(--muted); }
    .info .lines { display: flex; flex-direction: column; align-items: center; text-align: center; }
    .info .lines div:first-child { color: var(--ink); }
    .dice { display: flex; align-items: center; gap: calc(10 * var(--u)); color: var(--ink); animation: rise 200ms ease-out; }
    .dice .title { color: var(--muted); white-space: nowrap; }
    .pair { display: flex; gap: calc(2 * var(--u)); padding-bottom: calc(3 * var(--u)); border-bottom: calc(3 * var(--u)) solid #3a3f4e; }
    .pair.hit, .pair.excess { border-bottom-color: var(--hp); }
    .pair.backlash { border-bottom-color: var(--orange); }
    .die {
      width: calc(24 * var(--u)); height: calc(24 * var(--u)); display: flex; align-items: center; justify-content: center;
      background: #f4f1e8; color: #111; font-size: calc(15 * var(--t)); animation: roll 380ms ease-out;
    }
    .die.def { background: #b9c6ff; }
    .die.none { background: transparent; color: var(--muted); outline: calc(1 * var(--u)) dashed var(--muted); outline-offset: calc(-1 * var(--u)); }
    .dice .sum { white-space: nowrap; color: var(--gold); }
    @keyframes roll { 0% { transform: rotate(-160deg) scale(0.4); opacity: 0; } 100% { transform: none; opacity: 1; } }
    @keyframes rise { from { transform: translateY(calc(6 * var(--u))); opacity: 0; } }

    .hint { flex: 1; min-width: 0; font-size: calc(14 * var(--t)); color: var(--muted); }
    .hint .message { color: var(--orange); }
    .hint .busy { color: var(--ink); }
    .buttons { display: flex; gap: calc(8 * var(--u)); align-items: center; }
    .buttons .ask { color: var(--ink); margin-right: calc(4 * var(--u)); white-space: nowrap; }

    .b {
      all: unset; box-sizing: border-box; cursor: pointer; white-space: nowrap;
      padding: calc(9 * var(--u)) calc(16 * var(--u)); font-size: calc(15 * var(--t)); line-height: 1; color: var(--ink);
      background: #1a2030; border: calc(2 * var(--u)) solid rgba(255, 255, 255, 0.12);
      transition: background 120ms, border-color 120ms;
    }
    .b:hover:not(:disabled), .b:focus-visible { background: #263049; border-color: rgba(255, 255, 255, 0.3); }
    .b:active:not(:disabled) { transform: translateY(calc(1 * var(--u))); }
    .b.on { border-color: var(--gold); color: var(--gold); background: rgba(255, 210, 63, 0.12); }
    .b.primary { background: var(--gold); border-color: var(--gold); color: #14110a; }
    .b.primary:hover:not(:disabled) { background: #ffe07a; border-color: #ffe07a; }
    .b:disabled { opacity: 0.3; cursor: default; }
    .b.ghost { background: transparent; border-color: var(--line); color: var(--muted); padding: calc(7 * var(--u)) calc(12 * var(--u)); font-size: calc(13 * var(--t)); }
    .b.ghost:hover { color: var(--ink); }
    .b.danger { border-color: var(--red); color: var(--red); }

    /* ------------------------------------------------------------ overlays */
    .log {
      position: absolute; right: 0; top: var(--band); bottom: var(--band); width: var(--rail); box-sizing: border-box;
      padding: calc(10 * var(--u)) calc(12 * var(--u)); overflow-y: auto; scrollbar-width: thin;
      background: rgba(11, 14, 21, 0.97); border-left: calc(1 * var(--u)) solid var(--line);
      font-size: calc(12 * var(--t)); line-height: 1.35; color: var(--muted);
    }
    .log p { margin: 0 0 calc(5 * var(--u)); }
    .log p:last-child { color: var(--ink); }
    .veil { position: absolute; inset: 0; background: rgba(4, 6, 10, 0.72); display: flex; align-items: center; justify-content: center; }
    .box {
      --ui-scale: 1.15;
      background: #0f131c; border: calc(1 * var(--u)) solid var(--line); border-top: calc(3 * var(--u)) solid var(--gold);
      padding: calc(26 * var(--u)) calc(32 * var(--u)); display: flex; flex-direction: column; gap: calc(10 * var(--u));
      max-width: 92vw; max-height: 90vh; overflow-y: auto; box-sizing: border-box;
    }
    .box.menu { width: calc(720 * var(--u)); }
    .box .settings { margin: calc(8 * var(--u)) 0; }
    .box h2 { margin: 0 0 calc(6 * var(--u)); font-weight: normal; font-size: calc(34 * var(--t)); color: var(--gold); }
    .box h3 { margin: calc(12 * var(--u)) 0 0; font-weight: normal; font-size: calc(17 * var(--t)); color: var(--muted); letter-spacing: 0.06em; text-transform: uppercase; }
    .box ul { margin: 0; padding-left: calc(20 * var(--u)); display: flex; flex-direction: column; gap: calc(6 * var(--u)); font-size: calc(14 * var(--t)); line-height: 1.35; color: var(--muted); }
    .box .b { text-align: center; }
    .box.over { align-items: center; text-align: center; padding: calc(36 * var(--u)) calc(56 * var(--u)); }
    .box.over h2 { font-size: calc(48 * var(--t)); margin: 0; }
    .box.over .reason { color: var(--ink); font-size: calc(18 * var(--t)); max-width: calc(860 * var(--u)); }
    .box.over .rule { color: var(--muted); font-size: calc(13 * var(--t)); }
    .sides { display: flex; gap: calc(20 * var(--u)); margin: calc(10 * var(--u)) 0; flex-wrap: wrap; justify-content: center; }
    .side {
      display: flex; flex-direction: column; align-items: center; gap: calc(6 * var(--u)); min-width: calc(260 * var(--u));
      padding: calc(14 * var(--u)) calc(18 * var(--u)); background: var(--surface); border-top: calc(3 * var(--u)) solid var(--team); opacity: 0.75;
    }
    .side.won { background: var(--team-soft); opacity: 1; }
    .side .name { color: var(--team); font-size: calc(18 * var(--t)); }
    .side .points { font-size: calc(40 * var(--t)); line-height: 1; color: var(--ink); }
    .side .points small { font-size: calc(14 * var(--t)); color: var(--muted); }
    .side .line { font-size: calc(13 * var(--t)); color: var(--muted); }
    .veil.soft { background: rgba(4, 6, 10, 0.45); }
    .box.banner { align-items: center; text-align: center; min-width: calc(520 * var(--u)); padding: calc(28 * var(--u)) calc(48 * var(--u)); animation: rise 250ms ease-out; }
    .box.banner .ended { color: var(--muted); font-size: calc(18 * var(--t)); letter-spacing: 0.06em; text-transform: uppercase; }
    .box.banner h2 { margin: 0; }
    .rolls { display: flex; gap: calc(48 * var(--u)); margin: calc(6 * var(--u)) 0; }
    .roll { display: flex; flex-direction: column; align-items: center; gap: calc(8 * var(--u)); color: var(--team); font-size: calc(15 * var(--t)); opacity: 0.5; }
    .roll.won { opacity: 1; }
    .roll .die { width: calc(56 * var(--u)); height: calc(56 * var(--u)); font-size: calc(32 * var(--t)); border-bottom: calc(4 * var(--u)) solid var(--team); animation: roll 600ms ease-out; }
    .box.banner .result { color: var(--gold); font-size: calc(19 * var(--t)); }
    .box.banner .ask { color: var(--ink); margin-top: calc(8 * var(--u)); }
    .box.banner .rule { color: var(--muted); font-size: calc(13 * var(--t)); }
    .tests { display: grid; grid-template-columns: auto auto auto; gap: calc(10 * var(--u)) calc(24 * var(--u)); align-items: center; margin: calc(8 * var(--u)) 0; text-align: left; }
    .test { display: contents; }
    .test .unit { color: var(--team); font-size: calc(16 * var(--t)); }
    .test .unit small { color: var(--muted); font-size: calc(12 * var(--t)); }
    .test .die { width: auto; height: auto; padding: calc(6 * var(--u)) calc(10 * var(--u)); font-size: calc(16 * var(--t)); justify-self: center; white-space: nowrap; }
    .test .outcome { font-size: calc(16 * var(--t)); }
    .test .outcome.ok { color: var(--hp); }
    .test .outcome.bad { color: var(--orange); }
    .box.banner .chosen { color: var(--ink); font-size: calc(19 * var(--t)); margin-top: calc(8 * var(--u)); animation: rise 250ms ease-out; }
    .row { display: flex; gap: calc(10 * var(--u)); margin-top: calc(10 * var(--u)); }

    /* ------------------------------------------------------------ tutorial */
    .hl { outline: calc(3 * var(--u)) solid var(--gold); outline-offset: calc(2 * var(--u)); animation: hl 900ms steps(2) infinite; }
    @keyframes hl { 50% { outline-color: rgba(255, 210, 63, 0.15); } }
    .tut {
      position: absolute; left: var(--rail); right: var(--rail); bottom: var(--band); height: var(--tut); box-sizing: border-box;
      display: flex; align-items: center; gap: calc(18 * var(--u)); padding: calc(14 * var(--u)) calc(18 * var(--u)) calc(10 * var(--u));
      background: #0f131c; border-top: calc(3 * var(--u)) solid var(--gold); border-bottom: calc(1 * var(--u)) solid var(--line);
    }
    .tut .bar { position: absolute; left: 0; top: calc(-3 * var(--u)); height: calc(3 * var(--u)); background: #7fe08f; transition: width 300ms steps(4); }
    .tut .label { position: absolute; left: calc(18 * var(--u)); top: calc(-12 * var(--u)); padding: calc(2 * var(--u)) calc(8 * var(--u)); background: var(--gold); color: #14110a; font-size: calc(11 * var(--t)); letter-spacing: 0.08em; text-transform: uppercase; }
    .tut .text { flex: 1; min-width: 0; font-size: calc(15 * var(--t)); line-height: 1.4; color: var(--ink); }
    .tut .text b { font-weight: normal; color: var(--gold); }
    .tut .actions { display: flex; flex-direction: column; align-items: stretch; gap: calc(6 * var(--u)); }
    .tut.sa { animation: shake-a 320ms steps(8); }
    .tut.sb { animation: shake-b 320ms steps(8); }
    @keyframes shake-a { 20% { transform: translateX(calc(-10 * var(--u))); } 40% { transform: translateX(calc(10 * var(--u))); } 60% { transform: translateX(calc(-6 * var(--u))); } 80% { transform: translateX(calc(6 * var(--u))); } }
    @keyframes shake-b { 20% { transform: translateX(calc(-10 * var(--u))); } 40% { transform: translateX(calc(10 * var(--u))); } 60% { transform: translateX(calc(-6 * var(--u))); } 80% { transform: translateX(calc(6 * var(--u))); } }
  `]

  /** `hl` when the tutorial points at this button */
  private hl(button: string): string {
    return this.view?.tutorial?.highlight.button === button ? 'hl' : ''
  }

  /** `hl` when the tutorial points at this part of the HUD */
  private pointedPart(part: 'rosters' | 'turn' | 'dice'): string {
    return this.view?.tutorial?.highlight.part === part ? 'hl' : ''
  }

  private scale = () => {
    this.style.setProperty('--s', String(hudScale()))
  }

  connectedCallback() {
    super.connectedCallback()
    this.scale()
    window.addEventListener('resize', this.scale)
  }

  disconnectedCallback() {
    window.removeEventListener('resize', this.scale)
    super.disconnectedCallback()
  }

  // ------------------------------------------------------------ rails

  private rail(roster: RosterView, side: 'left' | 'right', team: string) {
    return html`
      <div class="rail ${side} ${team} interactive">
        <div class="head ${roster.active ? 'active' : ''} ${this.pointedPart('rosters')}">
          <div><span class="name">${roster.name}</span>${roster.active ? html`<span class="turn">${t().onagro.unit.yourTurn}</span>` : nothing}</div>
          <span class="score">${roster.score}</span>
        </div>
        ${roster.units.map(unit => this.tile(unit))}
      </div>`
  }

  private tile(unit: RosterUnitView) {
    const text = t().onagro.unit
    const pointed = !!this.view?.tutorial?.highlight.units.includes(unit.id)
    const classes = ['tile', unit.selected ? 'selected' : '', unit.hovered ? 'hovered' : '', unit.done ? 'done' : '', unit.out ? 'out' : '', pointed ? 'hl' : ''].join(' ')
    const pips = Array.from({ length: unit.maxHp }, (_, i) => html`<i class=${i < unit.hp ? 'on' : ''}></i>`)
    const tag = unit.out ? html`<span class="tag">${text.out}</span>` : nothing
    return html`
      <div class=${classes}
        @click=${() => { if (!unit.out) send(this, 'pick-unit', unit.id) }}
        @mouseenter=${() => send(this, 'hover-unit', unit.id)}
        @mouseleave=${() => send(this, 'hover-unit', null)}>
        <div class="face"><img src=${unit.portrait} alt="" /></div>
        <div class="who">
          <b>${unit.name}</b>
          <div class="pips ${unit.hp * 2 <= unit.maxHp && unit.hp < unit.maxHp ? 'low' : ''}">${pips}</div>
          ${unit.markers.length > 0 ? html`
            <div class="marks">
              ${unit.markers.map(mark => html`<span class="mark" title=${mark.help}><img src=${mark.icon} alt="" />${mark.label}</span>`)}
            </div>` : nothing}
        </div>
        ${tag}
        ${unit.detail ? this.detail(unit.detail) : nothing}
      </div>`
  }

  private detail(unit: UnitCardView) {
    const s = t().stats
    const stat = (label: string, value: number | string, changed = false) => html`<div><small>${label}</small><b class=${changed ? 'up' : ''}>${value}</b></div>`
    return html`
      <div class="detail" @click=${(event: Event) => event.stopPropagation()}>
        <div class="meta">${unit.classLabel}${unit.commander ? html` · ${t().onagro.unit.commander}` : nothing}${unit.ranged ? html` · ${unit.ranged}` : nothing}</div>
        <div class="stats">
          ${stat(s.mov, unit.stats.mo)}${stat('A', unit.stats.a)}${stat(s.atk, unit.stats.pa)}
          ${stat(s.def, unit.pd, unit.pdUp)}${stat('M', unit.morale, unit.moraleUp)}
          ${stat(s.hp, `${unit.hp}/${unit.stats.pv}`)}
        </div>
        ${unit.markers.map(mark => html`<div class="mark-help"><img src=${mark.icon} alt="" /><span><b>${mark.label}:</b> ${mark.help}</span></div>`)}
        ${unit.status.length > 0 ? html`<div class="tags">${unit.status.map(text => html`<span class="tag warn">${text}</span>`)}</div>` : nothing}
        ${unit.abilities.map(text => html`<div class="note">${text}</div>`)}
        ${unit.spells.map(spell => html`<div class="spell"><b>${spell.name}</b> · ${spell.state}<br /><span>${spell.text}</span></div>`)}
        ${unit.terrain ? html`<div class="meta">${unit.terrain}</div>` : nothing}
      </div>`
  }

  // ------------------------------------------------------------ bands

  /** The middle of the top band: the last dice, else the forecast, else the hex under the pointer */
  private info(view: HudView) {
    if (view.dice) {
      return html`
        <div class="dice ${this.pointedPart('dice')}">
          <span class="title">${view.dice.title}</span>
          ${view.dice.pairs.map(pair => html`
            <span class="pair ${pair.effect}" title=${pair.label}>
              <span class="die">${pair.attack}</span>
              <span class="die def ${pair.defense === null ? 'none' : ''}">${pair.defense ?? '–'}</span>
            </span>`)}
          <span class="sum">${view.dice.summary}</span>
        </div>`
    }
    if (view.hoverLines.length > 0) return html`<div class="lines">${view.hoverLines.map(line => html`<div>${line}</div>`)}</div>`
    if (view.terrainLines.length > 0) {
      return html`<div class="lines"><div>${view.terrainLines[0]}</div><div>${view.terrainLines.slice(1).join(' · ')}</div></div>`
    }
    return nothing
  }

  private buttons(view: HudView) {
    const text = t().onagro
    const bar = view.actions
    if (!bar) return nothing
    const pick = (kind: string, spell?: string) => () => send(this, 'pick-action', { kind, spell })
    return html`
      <div class="buttons">
        <button class="b ${bar.mode === 'move' ? 'on' : ''} ${this.hl('move')}" ?disabled=${!bar.move} @click=${pick('move')}>${text.actions.move}</button>
        <button class="b ${bar.mode === 'shoot' ? 'on' : ''} ${this.hl('shoot')}" ?disabled=${!bar.shoot} @click=${pick('shoot')}>${text.actions.shoot}</button>
        ${bar.spells.map(spell => html`<button class="b ${bar.mode === 'cast' && bar.spell === spell.id ? 'on' : ''} ${this.hl(spell.id)}" ?disabled=${!spell.enabled} @click=${pick('cast', spell.id)}>${spell.label}</button>`)}
        <button class="b primary ${this.hl('hold')}" ?disabled=${!bar.hold} @click=${() => send(this, 'hold')}>${bar.holdLabel}</button>
      </div>`
  }

  private banner(banner: TurnBannerView) {
    return html`
      <div class="veil soft interactive">
        <div class="box banner">
          ${banner.ended ? html`<div class="ended">${banner.ended}</div>` : nothing}
          <h2>${banner.title}</h2>
          <h3>${banner.rollsTitle}</h3>
          <div class="rolls">
            ${banner.rolls.map(roll => html`
              <div class="roll team-${roll.team} ${roll.won ? 'won' : ''}">
                <span class="die">${roll.roll}</span>
                <span>${roll.name}</span>
              </div>`)}
          </div>
          <div class="result">${banner.result}</div>
          ${banner.choose ? html`
            <div class="ask">${banner.choose.question}</div>
            <div class="row">
              ${banner.choose.options.map(option => html`<button class="b primary ${this.hl(`first-${option.player}`)}" @click=${() => send(this, 'choose-first', option.player)}>${option.label}</button>`)}
            </div>` : nothing}
          ${banner.chosen ? html`<div class="chosen">${banner.chosen}</div>` : nothing}
          ${banner.ok ? html`<div class="row"><button class="b ${this.hl('ok')}" @click=${() => send(this, 'dismiss-banner')}>${banner.ok}</button></div>` : nothing}
        </div>
      </div>`
  }

  private morale(morale: MoraleBannerView) {
    return html`
      <div class="veil soft interactive">
        <div class="box banner">
          <h2>${morale.title}</h2>
          <div class="rule">${morale.rule}</div>
          <div class="tests">
            ${morale.rows.map(row => html`
              <div class="test team-${row.team}">
                <span class="unit">${row.name}${row.tag ? html` <small>(${row.tag})</small>` : nothing}</span>
                <span class="die">${row.roll}</span>
                <span class="outcome ${row.passed ? 'ok' : 'bad'}">${row.result}</span>
              </div>`)}
          </div>
          <div class="row"><button class="b ${this.hl('ok')}" @click=${() => send(this, 'dismiss-banner')}>${morale.ok}</button></div>
        </div>
      </div>`
  }

  private tutorialPanel(tut: TutorialView) {
    // [text] in gold, as in the hints
    const parts = tut.text.split(/(\[[^\]]+\])/).map(part => part.startsWith('[') ? html`<b>${part.slice(1, -1)}</b>` : part)
    const shake = tut.shake === 0 ? '' : tut.shake % 2 ? 'sa' : 'sb'
    return html`
      <div class="tut interactive ${shake}">
        <div class="bar" style="width: ${Math.round(tut.progress * 100)}%"></div>
        <span class="label">${tut.title}</span>
        <div class="text">${parts}</div>
        <div class="actions">
          ${tut.canNext ? html`<button class="b primary" @click=${() => send(this, 'tutorial-next')}>${tut.next}</button>` : nothing}
          <button class="b ghost ${tut.skipArmed ? 'danger' : ''}" @click=${() => send(this, 'tutorial-skip')}>${tut.skip}</button>
        </div>
      </div>`
  }

  protected render() {
    const view = this.view
    if (!view) return nothing
    const text = t().onagro
    return html`
      ${this.rail(view.rosters[0], 'left', `team-${view.rosters[0].team}`)}
      ${this.rail(view.rosters[1], 'right', `team-${view.rosters[1].team}`)}

      <div class="band top interactive">
        <div class="phase ${this.pointedPart('turn')}">
          <strong>${view.turnText} <span>· ${view.phaseText}</span></strong>
          <small>${view.sideText}</small>
        </div>
        <div class="info">${this.info(view)}</div>
        <button class="b ghost" @click=${() => send(this, 'open-menu')}>${view.menuButton}</button>
      </div>

      <div class="band bottom interactive">
        <div class="hint">
          ${view.message ? html`<span class="message">${view.message}</span>` : view.busy ? html`<span class="busy">${text.cpuPlaying}</span>` : view.hint}
        </div>
        ${view.busy ? nothing : this.buttons(view)}
      </div>

      ${view.showLog ? html`<div class="log interactive">${view.log.map(line => html`<p>${line}</p>`)}</div>` : nothing}

      ${view.banner && !view.morale ? this.banner(view.banner) : nothing}
      ${view.morale ? this.morale(view.morale) : nothing}

      ${view.tutorial && !view.over ? this.tutorialPanel(view.tutorial) : nothing}

      ${view.menu ? html`
        <div class="veil interactive">
          <div class="box menu">
            ${view.menu.options ? html`
              <h2>${view.menu.optionsLabel}</h2>
              <button class="b" @click=${() => send(this, 'toggle-log')}>${view.menu.logLabel}</button>
              <button class="b" @click=${() => send(this, 'toggle-grid')}>${view.menu.gridLabel}</button>
              <settings-controls class="settings" languages></settings-controls>
              <button class="b primary" @click=${() => send(this, 'close-options')}>${view.menu.backLabel}</button>` : html`
              <h2>${view.menu.title}</h2>
              <button class="b primary" @click=${() => send(this, 'close-menu')}>${view.menu.resume}</button>
              <button class="b" @click=${() => send(this, 'open-options')}>${view.menu.optionsLabel}</button>
              <button class="b ${view.menu.confirmQuit ? 'danger' : ''}" @click=${() => send(this, 'quit')}>${view.menu.confirmQuit ? text.menuScreen.quitSure : view.menu.quit}</button>
              <h3>${view.menu.controlsTitle}</h3>
              <ul>${view.menu.controls.map(line => html`<li>${line}</li>`)}</ul>`}
          </div>
        </div>` : nothing}

      ${view.over ? html`
        <div class="veil interactive">
          <div class="box over">
            <h2>${view.over.title}</h2>
            <div class="reason">${view.over.reason}</div>
            <div class="sides">
              ${view.over.sides.map(side => html`
                <div class="side team-${side.team} ${side.won ? 'won' : ''}">
                  <div class="name">${side.name}</div>
                  ${side.won ? html`<span class="tag gold">${text.over.winner}</span>` : nothing}
                  <div class="points">${side.points} <small>${text.over.points}</small></div>
                  ${side.lines.map(line => html`<div class="line">${line}</div>`)}
                </div>`)}
            </div>
            <div class="rule">${view.over.rule}</div>
            <div class="row">
              <button class="b primary" @click=${() => send(this, 'again')}>${view.over.again}</button>
              <button class="b" @click=${() => send(this, 'menu')}>${text.over.menu}</button>
            </div>
          </div>
        </div>` : nothing}
    `
  }

  updated() {
    // keep the newest log line in view
    const log = this.renderRoot.querySelector('.log')
    if (log) log.scrollTop = log.scrollHeight
  }
}

declare global {
  interface HTMLElementTagNameMap { 'onagro-hud': OnagroHud }
}
