/**
 * The guide's markers, as tokens beside a unit on the map: commander, Moral failures
 * (Abalada, Retirada, Rendição), activated this turn, magic shield and spell recharging.
 * Each token is a dark chip with a border in the marker's color and a pixel-art icon
 * (rows of palette letters, '.' = empty) with the dark outline of the minis.
 * Wounds (the guide's Ferido) are the PV bar under the unit.
 */

import type { UnitState } from '../rules/units'

const PALETTE: Record<string, string> = {
  Y: '#ffd23f', // gold
  r: '#e0303a', // jewel
  o: '#ff8c42', // Moral failure
  W: '#f4f4f4', // white flag
  s: '#8a5a2b', // pole
  b: '#4cc9f0', // shield
  B: '#b8f0ff',
  p: '#c08cff', // hourglass
  y: '#ffd36b', // sand
  g: '#cfd3dc' // activated
}

const OUTLINE = '#0a0d2a'

export const MARKERS = {
  commander: [
    'Y..Y..Y',
    'YY.Y.YY',
    'YYYYYYY',
    'YrYYYrY',
    'YYYYYYY'
  ],
  /** Abalada (one failure) */
  shaken: [
    'oo',
    'oo',
    'oo',
    '..',
    'oo'
  ],
  /** Retirada (two failures) */
  retreating: [
    'oo.oo',
    'oo.oo',
    'oo.oo',
    '.....',
    'oo.oo'
  ],
  /** Rendição (three failures): white flag */
  surrendering: [
    'sWWWW',
    'sWWWW',
    'sWWW.',
    's....',
    's....'
  ],
  /** Ativado: already acted this turn */
  activated: [
    '....g',
    '...gg',
    'g.gg.',
    'ggg..',
    '.g...'
  ],
  shield: [
    'bbbbb',
    'bBBBb',
    'bBBBb',
    '.bBb.',
    '..b..'
  ],
  recharge: [
    'ppppp',
    '.yyy.',
    '..y..',
    '.p.p.',
    'ppppp'
  ]
} as const

export type Marker = keyof typeof MARKERS

/** The border of each token: the color of its icon */
const BORDER: Record<Marker, string> = {
  commander: '#ffd23f',
  shaken: '#ff8c42',
  retreating: '#ff8c42',
  surrendering: '#f4f4f4',
  activated: '#8b90a0',
  shield: '#4cc9f0',
  recharge: '#c08cff'
}

/** Draws a marker's icon with its top-left corner at (x, y) */
function drawIcon(ctx: CanvasRenderingContext2D, marker: Marker, x: number, y: number, pixel: number): void {
  const rows = MARKERS[marker]
  const each = (paint: (px: number, py: number, letter: string) => void) =>
    rows.forEach((line, py) => [...line].forEach((letter, px) => {
      if (PALETTE[letter]) paint(px, py, letter)
    }))
  ctx.fillStyle = OUTLINE
  each((px, py) => ctx.fillRect(x + (px - 1) * pixel, y + (py - 1) * pixel, pixel * 3, pixel * 3))
  each((px, py, letter) => {
    ctx.fillStyle = PALETTE[letter]
    ctx.fillRect(x + px * pixel, y + py * pixel, pixel, pixel)
  })
}

/** Draws a marker as a square token of `size` pixels with its top-left corner at (x, y) */
export function drawToken(ctx: CanvasRenderingContext2D, marker: Marker, x: number, y: number, size: number): void {
  ctx.fillStyle = 'rgba(10, 13, 22, 0.88)'
  ctx.fillRect(x, y, size, size)
  ctx.strokeStyle = BORDER[marker]
  ctx.lineWidth = 2
  ctx.strokeRect(x + 1, y + 1, size - 2, size - 2)
  const rows = MARKERS[marker]
  const width = rows[0].length
  const height = rows.length
  // as big as fits with a border of room; the wide crown gets smaller pixels
  const pixel = Math.max(1, Math.min(3, Math.floor((size - 8) / Math.max(width, height))))
  drawIcon(ctx, marker, x + Math.round((size - width * pixel) / 2), y + Math.round((size - height * pixel) / 2), pixel)
}

/** The markers of a unit: commander and Moral on the left of the sprite, activated, shield and recharge on the right */
export function unitMarkers(unit: UnitState, activated: boolean, turn: number): { left: Marker[], right: Marker[] } {
  const left: Marker[] = []
  if (unit.commander) left.push('commander')
  if (unit.moraleFailures > 0) left.push(unit.moraleFailures === 1 ? 'shaken' : unit.moraleFailures === 2 ? 'retreating' : 'surrendering')
  const right: Marker[] = []
  if (activated) right.push('activated')
  if (unit.shield) right.push('shield')
  if (Object.values(unit.spellReadyOn).some(readyOn => readyOn !== undefined && readyOn > turn)) right.push('recharge')
  return { left, right }
}

/** Side of the token pictures used by the HUD */
const ICON_SIZE = 26
const icons = new Map<Marker, string>()

/** A token as a data URL (troop lists), the same picture as on the map */
export function markerIcon(marker: Marker): string {
  let url = icons.get(marker)
  if (!url) {
    const canvas = document.createElement('canvas')
    canvas.width = ICON_SIZE
    canvas.height = ICON_SIZE
    const ctx = canvas.getContext('2d')
    if (ctx) drawToken(ctx, marker, 0, 0, ICON_SIZE)
    url = canvas.toDataURL()
    icons.set(marker, url)
  }
  return url
}
