import { Axial, HexLayout, axialToOffset, pixelToHex } from '../hex'
import { MapData, inMap, parseMap } from '../rules/terrain'
import type { Placement } from '../rules/units'
import { TROOPS, TroopId } from '../rules/sheets'
import { Edge, defaultDeployment } from '../rules/deploy'
import { ART_HEIGHT, ART_WIDTH, GRID_COLS, MAP1_TERRAIN, MAP2_TERRAIN, MAP3_TERRAIN } from './map-terrain'

/**
 * The maps as the rules see them (no engine: the tests and the simulations use this) and the grid
 * every map shares: pointy-top regular hexes laid over 2048 x 1408 art, odd rows shifted right.
 */
export const MAP1: MapData = parseMap(MAP1_TERRAIN, 'pointy')
export const MAP2: MapData = parseMap(MAP2_TERRAIN, 'pointy')
export const MAP3: MapData = parseMap(MAP3_TERRAIN, 'pointy')

const HEX_WIDTH = ART_WIDTH / (GRID_COLS + 0.5)

export const GRID_LAYOUT: HexLayout = { orientation: 'pointy', sizeX: HEX_WIDTH / Math.sqrt(3), sizeY: HEX_WIDTH / Math.sqrt(3) }

export const ART_SIZE = { width: ART_WIDTH, height: ART_HEIGHT }

/** Center of the hex at column/row, in art pixels */
export function hexCenter(col: number, row: number): { x: number, y: number } {
  return { x: HEX_WIDTH * (col + 0.5 + 0.5 * (row & 1)), y: GRID_LAYOUT.sizeY * (1 + 1.5 * row) }
}

/** Center of a hex (axial), in art pixels */
export function hexPixel(hex: Axial): { x: number, y: number } {
  const { col, row } = axialToOffset(hex, 'pointy')
  return hexCenter(col, row)
}

/** The hex under an art pixel of `map` (null outside it) */
export function hexAt(map: MapData, x: number, y: number): Axial | null {
  // the grid starts at the top-left of the first hex: hex (0, 0) is centered on (HEX_WIDTH / 2, sizeY)
  const hex = pixelToHex({ x: x - HEX_WIDTH / 2, y: y - GRID_LAYOUT.sizeY }, GRID_LAYOUT)
  return inMap(map, hex) ? hex : null
}

/** Both troops in the standard formation on `map`: `troops[0]` (player 0) on `edges[0]` (the simulations use west × east) */
export function startingArmies(troops: [TroopId, TroopId] = ['human', 'orc'], edges: [Edge, Edge] = ['west', 'east'], map: MapData = MAP1): [Placement[], Placement[]] {
  return [defaultDeployment(map, TROOPS[troops[0]], edges[0]), defaultDeployment(map, TROOPS[troops[1]], edges[1])]
}
