import { LitElement, css, html, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import * as ex from 'excalibur'
import { Resources } from '../resources'
import { theme } from './theme'
import { readableBoost } from '../device'
import { pageStyles, renderCredits } from './start-screen-pages'
import { unitPortrait } from '../onagro/portraits'
import { AI_LEVELS, AiLevel } from '../rules/ai'
import { MatchOptions, ONAGRO_SCENE, tutorialOptions } from '../onagro/scene'
import { isTutorialDone } from '../tutorial/tutorial'
import { EDGES, Edge, defaultDeployment, oppositeEdge } from '../rules/deploy'
import { TROOPS, TROOP_IDS, TroopId } from '../rules/sheets'
import { MapId, mapById } from '../onagro/maps'
import type { OtherSide, TroopChoice } from './troop-deploy'
import { t } from '../i18n'
import LogoPath from '../assets/loader-logo.png'
import './settings-controls'
import './map-select'
import './troop-deploy'

/** Play: mode → map → each side's troop and deployment (player 2 too, in a two-player match) → match */
type Screen = 'title' | 'mode' | 'map' | 'army' | 'credits' | 'options'

const PREF_OPPONENT = 'onagro.opponent'

/** Who plays: a player against the AI, two players on the same screen, or two AIs (watch) */
type Mode = 'vsAi' | 'twoPlayers' | 'aiVsAi'

/** The mode remembered from the last match (older versions saved 'cpu' / 'human') */
function readMode(): Mode {
  const saved = readPref(PREF_OPPONENT)
  return saved === 'twoPlayers' || saved === 'human' ? 'twoPlayers' : saved === 'aiVsAi' ? 'aiVsAi' : 'vsAi'
}
const PREF_LEVEL = 'onagro.level'
const PREF_TROOP = 'onagro.troop'
const PREF_ENEMY = 'onagro.enemy'
const PREF_EDGE = 'onagro.edge'
const PREF_MAP = 'onagro.map'

function readPref(key: string): string | null {
  try { return localStorage.getItem(key) } catch { return null }
}
function writePref(key: string, value: string) {
  try { localStorage.setItem(key, value) } catch { /* storage unavailable: ignore */ }
}

/** Text size in the menus relative to the base sizes in the components */
const MENU_TEXT_SCALE = 1.3
/** Extra text size allowed on small screens (the layout itself doesn't grow) */
const MENU_MAX_TEXT_BOOST = 1.4
/** The title screen uses at most this share of the window height */
const TITLE_FIT = 0.94

/** Who stands on the title screen: the two troops of the guide (unit sheet ids) */
const BLUE = ['carolina', 'human-mage', 'human-archer', 'human-infantry', 'human-infantry']
const RED = ['reaver', 'orc-druid', 'orc-archer', 'orc-infantry', 'orc-infantry']

const readTroop = (key: string, fallback: TroopId): TroopId => {
  const value = readPref(key)
  return (TROOP_IDS as string[]).includes(value ?? '') ? value as TroopId : fallback
}

/**
 * Start screen: title menu (Play, Options, Credits), and before a match the mode, the map
 * and, for each side, the troop and where its units start. Mounted by main.ts and by the
 * match scene when it goes back to the menu.
 */
@customElement('start-screen-ui')
export class StartScreenUi extends LitElement {
  static styles = [theme, pageStyles, css`
    :host {
      position: fixed;
      inset: 0;
      z-index: 999;
      display: block;
      overflow: hidden;
    }
    .wrapper {
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      background:
        radial-gradient(ellipse at 50% 35%, rgba(61, 123, 255, 0.18), transparent 60%),
        repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.025) 0 calc(2 * var(--u)), transparent calc(2 * var(--u)) calc(64 * var(--u))),
        repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.025) 0 calc(2 * var(--u)), transparent calc(2 * var(--u)) calc(64 * var(--u))),
        #0b0d16;
    }
    .screen { animation: enter 260ms steps(4) both; }
    @keyframes enter { from { opacity: 0; transform: translateY(calc(16 * var(--u))); } }

    .title-screen { display: flex; flex-direction: column; align-items: center; gap: calc(56 * var(--u)); }
    /* the official logo (the same as the loading screen), with the tagline already in it; the negative margins cancel its transparent border (73 and 58 of 329 px), so the gaps around the units are even */
    .logo { width: calc(760 * var(--u)); height: auto; image-rendering: auto; margin: calc(-83 * var(--u)) 0 calc(-66 * var(--u)); filter: drop-shadow(calc(5 * var(--u)) calc(5 * var(--u)) 0 #000); }

    .armies { display: flex; align-items: center; gap: calc(4 * var(--u)); }
    .armies img { width: calc(120 * var(--u)); height: calc(120 * var(--u)); image-rendering: pixelated; animation: bob 900ms steps(2) infinite; }
    .armies .vs { font-size: calc(52 * var(--t)); color: var(--gold); margin: 0 calc(28 * var(--u)); text-shadow: calc(4 * var(--u)) calc(4 * var(--u)) 0 #000; }
    @keyframes bob { 50% { transform: translateY(calc(-4 * var(--u))); } }

    .menu { display: flex; flex-direction: column; gap: calc(12 * var(--u)); padding: calc(18 * var(--u)); width: calc(600 * var(--u)); }
    .menu .btn { font-size: calc(32 * var(--t)); padding: calc(12 * var(--u)) calc(18 * var(--u)); --team: #2a2d3a; text-align: center; white-space: nowrap; }
    .menu .btn.primary { --team: var(--blue); font-size: calc(40 * var(--t)); }

    .options-page { width: calc(760 * var(--u)); }

    /* Mode */
    .mode-screen { display: flex; flex-direction: column; align-items: center; gap: calc(28 * var(--u)); }
    .heading { margin: 0; font-weight: normal; font-size: calc(56 * var(--t)); text-shadow: calc(5 * var(--u)) calc(5 * var(--u)) 0 #000; }
    .modes { display: grid; grid-template-columns: repeat(4, calc(400 * var(--u))); gap: calc(22 * var(--u)); }
    .mode { position: relative; }
    .badge {
      position: absolute; top: calc(-14 * var(--u)); right: calc(16 * var(--u)); padding: calc(4 * var(--u)) calc(10 * var(--u));
      background: var(--gold); color: #14110a; font-size: calc(15 * var(--t)); animation: bob 900ms steps(2) infinite;
    }
    .mode {
      appearance: none;
      font: inherit;
      color: inherit;
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: calc(16 * var(--u));
      padding: calc(26 * var(--u)) calc(22 * var(--u));
      cursor: pointer;
      text-align: center;
      transition: transform 120ms steps(2);
    }
    .mode:hover, .mode:focus-visible { transform: translateY(calc(-6 * var(--u))); border-color: var(--gold); }
    .mode.last { border-color: var(--gold); }
    .sides { display: flex; align-items: center; gap: calc(14 * var(--u)); }
    .side { display: flex; flex-direction: column; align-items: center; gap: calc(6 * var(--u)); font-size: calc(18 * var(--t)); }
    .side img { width: calc(96 * var(--u)); height: calc(96 * var(--u)); image-rendering: pixelated; background: rgba(255, 255, 255, 0.05); }
    .side.blue span { color: var(--blue); }
    .side.red span { color: var(--red); }
    .sides .vs { font-size: calc(26 * var(--t)); color: var(--gold); }
    .mode h3 { margin: 0; font-weight: normal; font-size: calc(32 * var(--t)); }
    .mode p { margin: 0; font-size: calc(17 * var(--t)); line-height: 1.35; color: var(--muted); }
    .difficulty { display: flex; align-items: center; gap: calc(10 * var(--u)); font-size: calc(18 * var(--t)); }
    .difficulty .label { color: var(--muted); margin-right: calc(6 * var(--u)); }
    .difficulty .btn { --team: #2a2d3a; font-size: calc(20 * var(--t)); padding: calc(8 * var(--u)) calc(20 * var(--u)); }
    .difficulty .btn.on { --team: var(--blue); }
    .bottom { display: flex; gap: calc(14 * var(--u)); align-items: center; }
    .bottom .btn { --team: #2a2d3a; font-size: calc(24 * var(--t)); padding: calc(10 * var(--u)) calc(26 * var(--u)); }
    .bottom small { font-size: calc(14 * var(--t)); color: var(--muted); }

    .fade { position: absolute; inset: 0; background: #000; opacity: 0; pointer-events: none; transition: opacity 600ms steps(6); }
    .fade.visible { opacity: 1; pointer-events: auto; }
  `]

  @property({ attribute: false })
    engine!: ex.Engine

  @state()
  private screen: Screen = 'title'

  @state()
  private leaving = false

  /** Who plays, and how well the AI plays (remembered for the next match) */
  @state()
  private mode: Mode = readMode()

  @state()
  private level: AiLevel = (AI_LEVELS as string[]).includes(readPref(PREF_LEVEL) ?? '') ? readPref(PREF_LEVEL) as AiLevel : 'normal'

  @state()
  private map: MapId = mapById(readPref(PREF_MAP) ?? '').id

  /** Last troops and edge (the troop screen opens with them) */
  private troop: TroopId = readTroop(PREF_TROOP, 'human')
  private enemy: TroopId = readTroop(PREF_ENEMY, 'orc')
  private edge: Edge = (EDGES as string[]).includes(readPref(PREF_EDGE) ?? '') ? readPref(PREF_EDGE) as Edge : 'west'

  /** Two players: player 1's troop and deployment while player 2 chooses */
  @state()
  private first: TroopChoice | null = null

  private onResize = () => {
    this.updateScale()
    requestAnimationFrame(() => this.fitTitle())
  }

  override updated() {
    this.fitTitle()
  }

  /**
   * Phones: the text is enlarged to stay readable (readableBoost), and the
   * title screen then grew taller than a phone held sideways. When it doesn't
   * fit, shrink just that screen to the height available (with a small margin).
   */
  private fitTitle() {
    const el = this.renderRoot.querySelector<HTMLElement>('.title-screen')
    if (!el) return
    el.style.zoom = ''
    const height = el.getBoundingClientRect().height
    const room = window.innerHeight * TITLE_FIT
    if (height > room) el.style.zoom = (room / height).toFixed(3)
  }

  private onKeyDown = (event: KeyboardEvent) => {
    if (this.screen === 'map' || this.screen === 'army') return
    if (event.key === 'Escape' && this.screen !== 'title') this.go('title')
    else if (event.key === 'Enter' && this.screen === 'title' && !(event.target instanceof HTMLButtonElement)) this.go('mode')
  }

  override connectedCallback(): void {
    super.connectedCallback()
    this.updateScale()
    window.addEventListener('resize', this.onResize)
    window.addEventListener('keydown', this.onKeyDown)
    Resources.TitleMusic.loop = true
    Resources.TitleMusic.play()
  }

  override disconnectedCallback(): void {
    window.removeEventListener('resize', this.onResize)
    window.removeEventListener('keydown', this.onKeyDown)
    Resources.TitleMusic.stop()
    super.disconnectedCallback()
  }

  /**
   * 1 --u = 1 px at 1920x1080. The menus keep their layout size (they already
   * fill the screen) and only enlarge text, a bit more on phones.
   */
  private updateScale() {
    const scale = Math.min(window.innerWidth / 1920, window.innerHeight / 1080)
    const boost = Math.min(MENU_MAX_TEXT_BOOST, readableBoost(scale * MENU_TEXT_SCALE))
    this.style.setProperty('--s', scale.toFixed(4))
    this.style.setProperty('--text-scale', (MENU_TEXT_SCALE * boost).toFixed(4))
  }

  private go(screen: Screen) {
    Resources.SelectSound.play()
    this.screen = screen
  }

  /** The tutorial skips the map and the troops: it always plays map 1, Humans against the Undead */
  private async playTutorial() {
    if (this.leaving) return
    this.leaving = true
    Resources.SelectSound.play()
    await new Promise(resolve => window.setTimeout(resolve, 450))
    this.engine.goToScene(ONAGRO_SCENE, { sceneActivationData: tutorialOptions() })
    this.remove()
  }

  private chooseMode(mode: Mode) {
    this.mode = mode
    writePref(PREF_OPPONENT, mode)
    this.go('map')
  }

  private chooseLevel(level: AiLevel) {
    Resources.SelectSound.play()
    this.level = level
    writePref(PREF_LEVEL, level)
  }

  private chooseMap(map: MapId) {
    this.map = map
    writePref(PREF_MAP, map)
    this.first = null
    this.go('army')
  }

  /** A side confirmed its troop: player 2 goes next in a two-player match, else the match starts */
  private confirmTroop(choice: TroopChoice) {
    if (this.mode !== 'twoPlayers' || this.first) {
      void this.play(choice)
      return
    }
    this.troop = choice.troop
    this.edge = choice.edge
    writePref(PREF_TROOP, choice.troop)
    writePref(PREF_EDGE, choice.edge)
    this.first = choice
    Resources.SelectSound.play()
  }

  /** Back from a troop screen: player 2 goes back to player 1, player 1 to the maps */
  private backFromTroop() {
    if (this.first) {
      this.first = null
      Resources.SelectSound.play()
    } else {
      this.go('map')
    }
  }

  private async play(last: TroopChoice) {
    if (this.leaving) return
    this.leaving = true
    Resources.SelectSound.play()
    const map = mapById(this.map)
    let options: MatchOptions
    if (this.first) {
      // two players: `last` is player 2
      options = {
        cpu: [], level: this.level, map: map.id,
        troops: [this.first.troop, last.troop], edges: [this.first.edge, last.edge], placements: [this.first.positions, last.positions]
      }
    } else {
      const enemy = last.enemy ?? this.enemy
      const edge = oppositeEdge(last.edge)
      writePref(PREF_TROOP, last.troop)
      writePref(PREF_ENEMY, enemy)
      writePref(PREF_EDGE, last.edge)
      // against the AI, it takes side 1; watching, side 0 too (both in the standard formation)
      options = {
        cpu: this.mode === 'aiVsAi' ? [0, 1] : [1], level: this.level, map: map.id,
        troops: [last.troop, enemy], edges: [last.edge, edge],
        placements: [last.positions, defaultDeployment(map.data, TROOPS[enemy], edge).map(p => p.pos)]
      }
    }
    await new Promise(resolve => window.setTimeout(resolve, 450))
    this.engine.goToScene(ONAGRO_SCENE, { sceneActivationData: options })
    this.remove()
  }

  private renderTitle() {
    const blue = BLUE.map(type => unitPortrait(type))
    const red = RED.map(type => unitPortrait(type, true, 1))
    return html`
      <div class="screen title-screen">
        <img class="logo" src=${LogoPath} alt="ONAGRO" />
        <div class="armies">
          ${blue.map((src, i) => html`<img src=${src} alt="" style="animation-delay: ${i * 120}ms" />`)}
          <span class="vs">${t().common.vs}</span>
          ${red.map((src, i) => html`<img src=${src} alt="" style="animation-delay: ${(i + 5) * 120}ms" />`)}
        </div>
        <nav class="panel menu">
          <button class="btn btn-solid primary" @click=${() => this.go('mode')}>${t().title.play}</button>
          <button class="btn btn-solid" @click=${() => this.go('options')}>${t().title.options}</button>
          <button class="btn btn-solid" @click=${() => this.go('credits')}>${t().title.credits}</button>
        </nav>
      </div>
    `
  }

  private renderModes() {
    const text = t().onagro.modes
    const tutorial = t().tutorial.ui
    const modes:{ id: Mode, info: { title: string, description: string, sides: string[] }, faces: [string, string] }[] = [
      { id: 'vsAi', info: text.vsCpu, faces: ['carolina', 'reaver'] },
      { id: 'twoPlayers', info: text.twoPlayers, faces: ['human-archer', 'orc-druid'] },
      { id: 'aiVsAi', info: text.aiVsAi, faces: ['berdolock', 'ogroth'] }
    ]
    return html`
      <div class="screen mode-screen">
        <h2 class="heading">${text.heading}</h2>
        <div class="modes">
          <button class="panel mode" @click=${() => void this.playTutorial()}>
            ${isTutorialDone() ? nothing : html`<span class="badge">${tutorial.badge}</span>`}
            <div class="sides">
              <div class="side blue"><img src=${unitPortrait('carolina')} alt="" /><span>${tutorial.modeSides[0]}</span></div>
              <span class="vs">${t().common.vs}</span>
              <div class="side red"><img src=${unitPortrait('skeleton-infantry', true, 1)} alt="" /><span>${tutorial.modeSides[1]}</span></div>
            </div>
            <h3>${tutorial.modeTitle}</h3>
            <p>${tutorial.modeDescription}</p>
          </button>
          ${modes.map(mode => html`
            <button class="panel mode ${mode.id === this.mode ? 'last' : ''}" @click=${() => this.chooseMode(mode.id)}>
              <div class="sides">
                <div class="side blue"><img src=${unitPortrait(mode.faces[0])} alt="" /><span>${mode.info.sides[0]}</span></div>
                <span class="vs">${t().common.vs}</span>
                <div class="side red"><img src=${unitPortrait(mode.faces[1], true, 1)} alt="" /><span>${mode.info.sides[1]}</span></div>
              </div>
              <h3>${mode.info.title}</h3>
              <p>${mode.info.description}</p>
            </button>`)}
        </div>
        <div class="difficulty">
          <span class="label">${text.level}</span>
          ${AI_LEVELS.map(level => html`
            <button class="btn btn-solid ${level === this.level ? 'on' : ''}" @click=${() => this.chooseLevel(level)}>${text.levels[level]}</button>`)}
        </div>
        <div class="bottom">
          <button class="btn btn-solid" @click=${() => this.go('title')}>${t().common.back}</button>
          <small class="keys-only">${text.keys}</small>
        </div>
      </div>
    `
  }

  private renderMapSelect() {
    const modes = t().onagro.modes
    return html`
      <map-select class="screen" .initial=${this.map} modeLabel=${this.mode === 'vsAi' ? modes.vsCpu.title : this.mode === 'twoPlayers' ? modes.twoPlayers.title : modes.aiVsAi.title}
        @select=${() => Resources.SelectSound.play()}
        @start=${(event: CustomEvent<MapId>) => this.chooseMap(event.detail)}
        @back=${() => this.go('mode')}></map-select>
    `
  }

  private renderTroop() {
    const army = t().onagro.army
    const first = this.first
    const map = mapById(this.map)
    const confirm = (event: CustomEvent<TroopChoice>) => this.confirmTroop(event.detail)
    if (!first) {
      const label = this.mode === 'vsAi' ? army.you : this.mode === 'twoPlayers' ? army.player(1) : army.ai(1)
      return html`<troop-deploy class="screen" .map=${map} playerLabel=${label} ?vsCpu=${this.mode === 'vsAi'} ?watch=${this.mode === 'aiVsAi'} .other=${null}
        .initial=${{ troop: this.troop, enemy: this.enemy, edge: this.edge }} @confirm=${confirm} @back=${() => this.backFromTroop()}></troop-deploy>`
    }
    // player 2: the edge is the opposite one; any troop, player 1's too (in the other colors)
    const other: OtherSide = { troop: first.troop, edge: first.edge, positions: first.positions }
    return html`<troop-deploy class="screen" .map=${map} playerLabel=${army.player(2)} .other=${other}
      .initial=${{ troop: this.enemy, enemy: this.troop, edge: oppositeEdge(first.edge) }} @confirm=${confirm} @back=${() => this.backFromTroop()}></troop-deploy>`
  }

  private renderPage(title: string, body: unknown, extraClass = '') {
    return html`
      <div class="screen panel page ${extraClass}">
        <div class="panel-title">${title}</div>
        <div class="page-body">${body}</div>
        <div class="page-footer"><button class="btn btn-solid" @click=${() => this.go('title')}>${t().common.back}</button></div>
      </div>
    `
  }

  private renderScreen() {
    switch (this.screen) {
    case 'title': return this.renderTitle()
    case 'mode': return this.renderModes()
    case 'map': return this.renderMapSelect()
    case 'army': return this.renderTroop()
    case 'options': return this.renderPage(t().title.options, html`<settings-controls languages></settings-controls>`, 'options-page')
    case 'credits': return this.renderPage(t().title.credits, renderCredits())
    }
  }

  override render() {
    return html`
      <div class="wrapper">
        ${this.renderScreen()}
        <div class="fade ${this.leaving ? 'visible' : ''}"></div>
      </div>
    `
  }
}
